    50→/**
    51→ * Mesh generation (excluding triangulation) and processing.
    52→ * <p>
    53→ * Many of the methods within this class process an existing Delaunay
    54→ * triangulation; you may first generate such a triangulation from a shape using
    55→ * the
    56→ * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
    57→ * delaunayTriangulationMesh()} method.
    58→ * 
    59→ * @author Michael Carleton
    60→ * @since 1.2.0
    61→ */
    62→public class PGS_Meshing {
    63→
    64→	private PGS_Meshing() {
    65→	}
    66→
    67→	/**
    68→	 * Generates a shape consisting of polygonal faces of an <i>Urquhart graph</i>.
    69→	 * An Urquhart graph is obtained by removing the longest edge from each triangle
    70→	 * in a triangulation.
    71→	 * <p>
    72→	 * In practice this is a way to tessellate a shape into polygons (with the
    73→	 * resulting tessellation being in between a
    74→	 * {@link PGS_Triangulation#delaunayTriangulation(PShape) triangulation} and a
    75→	 * {@link micycle.pgs.PGS_Processing#convexPartition(PShape) partition}).
    76→	 * <p>
    77→	 * Note that this method processes a Delaunay triangulation. Process a shape
    78→	 * using
    79→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
    80→	 * delaunayTriangulationMesh()} first and then feed it to this method.
    81→	 * <p>
    82→	 * The <i>Urquhart graph</i> is a good approximation to the
    83→	 * {@link #relativeNeighborFaces(IIncrementalTin, boolean) <i>relative
    84→	 * neighborhood</i>} graph (having only about 2% additional edges).
    85→	 * 
    86→	 * @param triangulation     a triangulation mesh
    87→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
    88→	 *                          even if they should be removed according to the
    89→	 *                          urquhart condition
    90→	 * @return a GROUP PShape where each child shape is a single face
    91→	 * @since 1.1.0
    92→	 * @see #gabrielFaces(IIncrementalTin, boolean)
    93→	 */
    94→	public static PShape urquhartFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
    95→		final HashSet<IQuadEdge> edges = PGS.makeHashSet(triangulation.getMaximumEdgeAllocationIndex());
    96→		final HashSet<IQuadEdge> uniqueLongestEdges = PGS.makeHashSet(triangulation.getMaximumEdgeAllocationIndex());
    97→
    98→		final boolean notConstrained = triangulation.getConstraints().isEmpty();
    99→
   100→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   101→			final IConstraint constraint = t.getContainingRegion();
   102→			if (notConstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   103→				edges.add(t.getEdgeA().getBaseReference());
   104→				edges.add(t.getEdgeB().getBaseReference());
   105→				edges.add(t.getEdgeC().getBaseReference());
   106→				final IQuadEdge longestEdge = findLongestEdge(t).getBaseReference();
   107→				if (!preservePerimeter || (preservePerimeter && !longestEdge.isConstrainedRegionBorder())) {
   108→					uniqueLongestEdges.add(longestEdge);
   109→				}
   110→			}
   111→		});
   112→
   113→		edges.removeAll(uniqueLongestEdges);
   114→
   115→		final Collection<PEdge> meshEdges = new ArrayList<>(edges.size());
   116→		edges.forEach(edge -> meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y)));
   117→
   118→		return PGS.polygonizeEdges(meshEdges);
   119→	}
   120→
   121→	/**
   122→	 * Generates a shape consisting of polygonal faces of a <i>Gabriel graph</i>. A
   123→	 * Gabriel graph is obtained by removing each edge E from a triangulation if a
   124→	 * vertex lies within a circle of diameter = length(E), centered on the midpoint
   125→	 * of E.
   126→	 * <p>
   127→	 * In practice this is a way to tessellate a shape into polygons (with the
   128→	 * resulting tessellation being reminiscent of shattering the shape as if it
   129→	 * were glass).
   130→	 * <p>
   131→	 * Note that this method processes a Delaunay triangulation. Process a shape
   132→	 * using
   133→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   134→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   135→	 * 
   136→	 * @param triangulation     a triangulation mesh
   137→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   138→	 *                          even if they should be removed according to the
   139→	 *                          gabriel condition
   140→	 * @return a GROUP PShape where each child shape is a single face
   141→	 * @since 1.1.0
   142→	 * @see #urquhartFaces(IIncrementalTin, boolean)
   143→	 */
   144→	public static PShape gabrielFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   145→		final HashSet<IQuadEdge> edges = new HashSet<>();
   146→		final HashSet<Vertex> vertices = new HashSet<>();
   147→
   148→		final boolean notConstrained = triangulation.getConstraints().isEmpty();
   149→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   150→			final IConstraint constraint = t.getContainingRegion();
   151→			if (notConstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   152→				edges.add(t.getEdgeA().getBaseReference()); // add edge to set
   153→				edges.add(t.getEdgeB().getBaseReference()); // add edge to set
   154→				edges.add(t.getEdgeC().getBaseReference()); // add edge to set
   155→				vertices.add(t.getVertexA());
   156→				vertices.add(t.getVertexB());
   157→				vertices.add(t.getVertexC());
   158→			}
   159→		});
   160→
   161→		final PointIndex<Vertex> tree = KDTree.create(2, (p1, p2) -> {
   162→			final double deltaX = p1[0] - p2[0];
   163→			final double deltaY = p1[1] - p2[1];
   164→			return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
   165→		});
   166→		vertices.forEach(v -> tree.insert(new double[] { v.x, v.y }, v));
   167→
   168→		final HashSet<IQuadEdge> nonGabrielEdges = new HashSet<>(); // base references to edges that should be removed
   169→		edges.forEach(edge -> {
   170→			final double[] midpoint = midpoint(edge);
   171→			final Vertex near = tree.query1NN(midpoint).value();
   172→			if (near != edge.getA() && near != edge.getB()) {
   173→				if (!preservePerimeter || (preservePerimeter && !edge.isConstrainedRegionBorder())) {
   174→					nonGabrielEdges.add(edge); // base reference
   175→				}
   176→			}
   177→		});
   178→		edges.removeAll(nonGabrielEdges);
   179→
   180→		final Collection<PEdge> meshEdges = new ArrayList<>(edges.size());
   181→		edges.forEach(edge -> meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y)));
   182→
   183→		return PGS.polygonizeEdges(meshEdges);
   184→	}
   185→
   186→	/**
   187→	 * Generates a shape consisting of polygonal faces of a <i>Relative neighborhood
   188→	 * graph</i> (RNG).
   189→	 * <p>
   190→	 * An RNG is obtained by removing each edge E from a triangulation if any vertex
   191→	 * is nearer to both vertices of E than the length of E.
   192→	 * <p>
   193→	 * The RNG is a subgraph of the {@link #urquhartFaces(IIncrementalTin, boolean)
   194→	 * urquhart} graph, having only slightly fewer edges.
   195→	 * 
   196→	 * @param triangulation     a triangulation mesh
   197→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   198→	 *                          even if they should be removed according to the
   199→	 *                          relative neighbor condition
   200→	 * @return
   201→	 * @since 1.3.0
   202→	 */
   203→	public static PShape relativeNeighborFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   204→		SimpleGraph<Vertex, IQuadEdge> graph = PGS_Triangulation.toTinfourGraph(triangulation);
   205→		NeighborCache<Vertex, IQuadEdge> cache = new NeighborCache<>(graph);
   206→
   207→		Set<IQuadEdge> edges = new HashSet<>(graph.edgeSet());
   208→
   209→		/*
   210→		 * If any vertex is nearer to both vertices of an edge, than the length of the
   211→		 * edge, this edge does not belong in the RNG.
   212→		 */
   213→		graph.edgeSet().forEach(e -> {
   214→			double l = e.getLength();
   215→			cache.neighborsOf(e.getA()).forEach(n -> {
   216→				if (Math.max(n.getDistance(e.getA()), n.getDistance(e.getB())) < l) {
   217→					if (!preservePerimeter || (preservePerimeter && !e.isConstrainedRegionBorder())) {
   218→						edges.remove(e);
   219→					}
   220→				}
   221→			});
   222→			cache.neighborsOf(e.getB()).forEach(n -> {
   223→				if (Math.max(n.getDistance(e.getA()), n.getDistance(e.getB())) < l) {
   224→					if (!preservePerimeter || (preservePerimeter && !e.isConstrainedRegionBorder())) {
   225→						edges.remove(e);
   226→					}
   227→				}
   228→			});
   229→		});
   230→
   231→		List<PEdge> edgesOut = edges.stream().map(PGS_Triangulation::toPEdge).collect(Collectors.toList());
   232→
   233→		if (preservePerimeter) {
   234→			return PGS.polygonizeEdgesRobust(edgesOut);
   235→		} else {
   236→			return PGS.polygonizeEdges(edgesOut);
   237→		}
   238→
   239→	}
   240→
   241→	/**
   242→	 * Generates a shape consisting of polygonal faces formed by edges returned by a
   243→	 * greedy sparse spanner applied to a triangulation.
   244→	 * 
   245→	 * @param triangulation     a triangulation mesh
   246→	 * @param k                 the order of the spanner. Should be at least 1.
   247→	 *                          Higher numbers collapse more edges resulting in
   248→	 *                          larger faces, until a single face remains
   249→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   250→	 *                          even if they should be removed according to the
   251→	 *                          spanner condition
   252→	 * @return a GROUP PShape where each child shape is a single face
   253→	 * @since 1.3.0
   254→	 */
   255→	public static PShape spannerFaces(final IIncrementalTin triangulation, int k, final boolean preservePerimeter) {
   256→		SimpleGraph<PVector, PEdge> graph = PGS_Triangulation.toGraph(triangulation);
   257→		if (graph.edgeSet().isEmpty()) {
   258→			return new PShape();
   259→		}
   260→
   261→		k = Math.max(2, k); // min(2) since k=1 returns triangulation
   262→		GreedyMultiplicativeSpanner<PVector, PEdge> spanner = new GreedyMultiplicativeSpanner<>(graph, k);
   263→		List<PEdge> spannerEdges = spanner.getSpanner().stream().collect(Collectors.toList());
   264→		if (preservePerimeter) {
   265→			if (triangulation.getConstraints().isEmpty()) { // does not have constraints
   266→				spannerEdges.addAll(triangulation.getPerimeter().stream().map(PGS_Triangulation::toPEdge).collect(Collectors.toList()));
   267→			} else { // has constraints
   268→				spannerEdges.addAll(triangulation.getEdges().stream().filter(IQuadEdge::isConstrainedRegionBorder)
   269→						.map(PGS_Triangulation::toPEdge).collect(Collectors.toList()));
   270→			}
   271→		}
   272→
   273→		return PGS.polygonizeEdgesRobust(spannerEdges);
   274→	}
   275→
   276→	/**
   277→	 * Generates a (mesh-like) shape consisting of polygonal faces of the dual graph
   278→	 * of the given triangulation.
   279→	 * <p>
   280→	 * In practice, the resulting dual mesh has hexagonal-like cells.
   281→	 * <p>
   282→	 * Note that this method processes a Delaunay triangulation. Process a shape
   283→	 * using
   284→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   285→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   286→	 * <p>
   287→	 * If the input has been generated from a PShape, consider generating the
   288→	 * triangulation with <code>refinements > 1</code> for better dual mesh results.
   289→	 * 
   290→	 * @param triangulation a triangulation mesh
   291→	 * @return a GROUP PShape where each child shape is a single face
   292→	 * @since 1.2.0
   293→	 */
   294→	public static PShape dualFaces(final IIncrementalTin triangulation) {
   295→		// TODO SEE HOT: Hodge-Optimized Triangulations - use voronoi dual / HOT
   296→		final IncrementalTinDual dual = new IncrementalTinDual(triangulation);
   297→		final PShape dualMesh = dual.getMesh();
   298→		PGS_Conversion.setAllFillColor(dualMesh, Colors.WHITE);
   299→		PGS_Conversion.setAllStrokeColor(dualMesh, Colors.PINK, 2);
   300→		return dualMesh;
   301→	}
   302→
   303→	/**
   304→	 * Produces a quadrangulation from a triangulation, by splitting each triangle
   305→	 * into three quadrangles (using the <i>Catmull and Clark</i> technique). A
   306→	 * quadrangulation is a mesh where every face is a quadrangle.
   307→	 * <p>
   308→	 * Since this method employs a very simple technique to produce a
   309→	 * quadrangulation, the result is poor-quality, containing many helix-like
   310→	 * structures (it's not at all "regular").
   311→	 * <p>
   312→	 * Note that this method processes a Delaunay triangulation. Process a shape
   313→	 * using
   314→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   315→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   316→	 * 
   317→	 * @param triangulation a triangulation mesh
   318→	 * @return a GROUP PShape, where each child shape is one quadrangle
   319→	 * @since 1.2.0
   320→	 */
   321→	public static PShape splitQuadrangulation(final IIncrementalTin triangulation) {
   322→		// https://www.cs.mcgill.ca/~cs507/projects/1998/rachelp/welcome.html
   323→		final PShape quads = new PShape(PConstants.GROUP);
   324→
   325→		/*-
   326→		 * 1. Insert a Steiner point along the interior of every edge of each 
   327→		 * triangle.
   328→		 * 2. Insert an extra Steiner point in the interior of each triangle.
   329→		 * 3. Connect the Steiner point inside each triangle to the Steiner points on the
   330→		 * edges of that triangle.
   331→		 * Each triangle is converted into three quadrangles.
   332→		 */
   333→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   334→
   335→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   336→			final IConstraint constraint = t.getContainingRegion();
   337→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   338→				final PVector p1 = PGS_Triangulation.toPVector(t.getVertexA());
   339→				final PVector p2 = PGS_Triangulation.toPVector(t.getVertexB());
   340→				final PVector p3 = PGS_Triangulation.toPVector(t.getVertexC());
   341→				final PVector sA = PVector.add(p1, p2).div(2); // steiner point p1-p2
   342→				final PVector sB = PVector.add(p2, p3).div(2); // steiner point p2-p3
   343→				final PVector sC = PVector.add(p3, p1).div(2); // steiner point p3-p1
   344→
   345→				// compute ?barycenter? of triangle = interior steiner point
   346→				final PVector cSeg = PVector.add(sA, sB).div(2);
   347→				final PVector sI = PVector.add(cSeg, sC).div(2); // interior steiner point
   348→
   349→				// anti-clockwise, starting at original vertex
   350→				quads.addChild(PGS_Conversion.fromPVector(p1, sC, sI, sA, p1));
   351→				quads.addChild(PGS_Conversion.fromPVector(p2, sA, sI, sB, p2));
   352→				quads.addChild(PGS_Conversion.fromPVector(p3, sB, sI, sC, p3));
   353→			}
   354→		});
   355→
   356→		/*-
   357→		 * Now ideally "regularize" the mesh using techniques explored here:
   358→		 * https://acdl.mit.edu/ESP/Publications/AIAApaper2019-1988.pdf
   359→		 * https://acdl.mit.edu/ESP/Publications/IMR28.pdf
   360→		 */
   361→
   362→		PGS_Conversion.setAllFillColor(quads, Colors.WHITE);
   363→		PGS_Conversion.setAllStrokeColor(quads, Colors.PINK, 2);
   364→
   365→		return quads;
   366→	}
   367→
   368→	/**
   369→	 * Generates a quadrangulation from a triangulation by selectively removing (or
   370→	 * "collapsing") the edges shared by neighboring triangles (via edge coloring).
   371→	 * <p>
   372→	 * This method may be slow on large inputs (as measured by vertex count), owing
   373→	 * to the graph coloring it performs.
   374→	 * 
   375→	 * @param triangulation     a triangulation mesh
   376→	 * @param preservePerimeter whether to preserve the perimeter of the input
   377→	 *                          triangulation; when true, retains edges that lie on
   378→	 *                          the perimeter of the triangulation mesh that would
   379→	 *                          have otherwise been removed (this results in some
   380→	 *                          triangles being included in the output).
   381→	 * @return a GROUP PShape, where each child shape is one quadrangle
   382→	 * @since 1.2.0
   383→	 */
   384→	public static PShape edgeCollapseQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   385→		/*-
   386→		 * From 'Fast unstructured quadrilateral mesh generation'.
   387→		 * A better coloring approach is given in 'Face coloring in unstructured CFD codes'.
   388→		 * 
   389→		 * First partition the edges of the triangular mesh into three groups such that
   390→		 * no triangle has two edges of the same color (find groups by reducing to a
   391→		 * graph-coloring).
   392→		 * Then obtain an all-quadrilateral mesh by removing all edges of *one* 
   393→		 * particular color.
   394→		 */
   395→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   396→		final AbstractBaseGraph<IQuadEdge, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
   397→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   398→			final IConstraint constraint = t.getContainingRegion();
   399→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   400→				graph.addVertex(t.getEdgeA().getBaseReference());
   401→				graph.addVertex(t.getEdgeB().getBaseReference());
   402→				graph.addVertex(t.getEdgeC().getBaseReference());
   403→
   404→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeB().getBaseReference());
   405→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeC().getBaseReference());
   406→				graph.addEdge(t.getEdgeB().getBaseReference(), t.getEdgeC().getBaseReference());
   407→			}
   408→		});
   409→
   410→		Coloring<IQuadEdge> coloring = new RLFColoring<>(graph).getColoring();
   411→
   412→		final HashSet<IQuadEdge> perimeter = new HashSet<>(triangulation.getPerimeter());
   413→		if (!unconstrained) {
   414→			perimeter.clear(); // clear, the perimeter of constrained tin is unaffected by the constraint
   415→		}
   416→
   417→		final Collection<PEdge> meshEdges = new ArrayList<>();
   418→		coloring.getColors().forEach((edge, color) -> {
   419→			/*
   420→			 * "We can remove the edges of any one of the colors, however a convenient
   421→			 * choice is the one that leaves the fewest number of unmerged boundary
   422→			 * triangles". -- ideal, but not implemented here...
   423→			 */
   424→			// NOTE could now apply Topological optimization, as given in paper.
   425→			if ((color < 2) || (preservePerimeter && (edge.isConstrainedRegionBorder() || perimeter.contains(edge)))) {
   426→				meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   427→			}
   428→		});
   429→
   430→		PShape quads = PGS.polygonizeEdges(meshEdges);
   431→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   432→			return quads;
   433→		} else {
   434→			return removeHoles(quads, triangulation);
   435→		}
   436→	}
   437→
   438→	/**
   439→	 * Generates a quadrangulation from a triangulation by "inverting" triangles
   440→	 * (for each triangle, create edges joining its centroid to each of its
   441→	 * vertices).
   442→	 * <p>
   443→	 * This approach tends to create a denser quad mesh than
   444→	 * {@link #edgeCollapseQuadrangulation(IIncrementalTin, boolean)
   445→	 * <code>edgeCollapseQuadrangulation()</code>} on the same input.
   446→	 * 
   447→	 * @param triangulation     a triangulation mesh
   448→	 * @param preservePerimeter whether to preserve the perimeter of the input
   449→	 *                          triangulation; when true, retains edges that lie on
   450→	 *                          the perimeter of the triangulation mesh that would
   451→	 *                          have otherwise been removed (this results in some
   452→	 *                          triangles being included in the output).
   453→	 * @return a GROUP PShape, where each child shape is one quadrangle
   454→	 * @since 1.2.0
   455→	 */
   456→	public static PShape centroidQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   457→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   458→		final HashSet<PEdge> edges = new HashSet<>();
   459→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   460→			final IConstraint constraint = t.getContainingRegion();
   461→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   462→				Vertex centroid = centroid(t);
   463→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexA().x, t.getVertexA().y));
   464→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexB().x, t.getVertexB().y));
   465→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexC().x, t.getVertexC().y));
   466→			}
   467→		});
   468→
   469→		if (preservePerimeter) {
   470→			List<IQuadEdge> perimeter = triangulation.getPerimeter();
   471→			triangulation.edges().forEach(edge -> {
   472→				if (edge.isConstrainedRegionBorder() || (unconstrained && perimeter.contains(edge))) {
   473→					edges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   474→				}
   475→			});
   476→		}
   477→
   478→		final PShape quads = PGS.polygonizeEdges(edges);
   479→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   480→			return quads;
   481→		} else {
   482→			return removeHoles(quads, triangulation);
