   835→	private static double[] midpoint(final IQuadEdge edge) {
   836→		final Vertex a = edge.getA();
   837→		final Vertex b = edge.getB();
   838→		return new double[] { (a.x + b.x) / 2d, (a.y + b.y) / 2d };
   839→	}
