   313→	 * using
   314→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   315→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   316→	 * 
   317→	 * @param triangulation a triangulation mesh
   318→	 * @return a GROUP PShape, where each child shape is one quadrangle
   319→	 * @since 1.2.0
   320→	 */
   321→	public static PShape splitQuadrangulation(final IIncrementalTin triangulation) {
   322→		// https://www.cs.mcgill.ca/~cs507/projects/1998/rachelp/welcome.html
   323→		final PShape quads = new PShape(PConstants.GROUP);
   324→
   325→		/*-
   326→		 * 1. Insert a Steiner point along the interior of every edge of each 
   327→		 * triangle.
   328→		 * 2. Insert an extra Steiner point in the interior of each triangle.
   329→		 * 3. Connect the Steiner point inside each triangle to the Steiner points on the
   330→		 * edges of that triangle.
   331→		 * Each triangle is converted into three quadrangles.
   332→		 */
   333→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   334→
   335→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   336→			final IConstraint constraint = t.getContainingRegion();
   337→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   338→				final PVector p1 = PGS_Triangulation.toPVector(t.getVertexA());
   339→				final PVector p2 = PGS_Triangulation.toPVector(t.getVertexB());
   340→				final PVector p3 = PGS_Triangulation.toPVector(t.getVertexC());
   341→				final PVector sA = PVector.add(p1, p2).div(2); // steiner point p1-p2
   342→				final PVector sB = PVector.add(p2, p3).div(2); // steiner point p2-p3
   343→				final PVector sC = PVector.add(p3, p1).div(2); // steiner point p3-p1
   344→
   345→				// compute ?barycenter? of triangle = interior steiner point
   346→				final PVector cSeg = PVector.add(sA, sB).div(2);
   347→				final PVector sI = PVector.add(cSeg, sC).div(2); // interior steiner point
   348→
   349→				// anti-clockwise, starting at original vertex
   350→				quads.addChild(PGS_Conversion.fromPVector(p1, sC, sI, sA, p1));
   351→				quads.addChild(PGS_Conversion.fromPVector(p2, sA, sI, sB, p2));
   352→				quads.addChild(PGS_Conversion.fromPVector(p3, sB, sI, sC, p3));
   353→			}
   354→		});
   355→
   356→		/*-
   357→		 * Now ideally "regularize" the mesh using techniques explored here:
   358→		 * https://acdl.mit.edu/ESP/Publications/AIAApaper2019-1988.pdf
   359→		 * https://acdl.mit.edu/ESP/Publications/IMR28.pdf
   360→		 */
   361→
   362→		PGS_Conversion.setAllFillColor(quads, Colors.WHITE);
   363→		PGS_Conversion.setAllStrokeColor(quads, Colors.PINK, 2);
   364→
   365→		return quads;
   366→	}
   367→
   368→	/**
   369→	 * Generates a quadrangulation from a triangulation by selectively removing (or
   370→	 * "collapsing") the edges shared by neighboring triangles (via edge coloring).
   371→	 * <p>
   372→	 * This method may be slow on large inputs (as measured by vertex count), owing
   373→	 * to the graph coloring it performs.
   374→	 * 
   375→	 * @param triangulation     a triangulation mesh
   376→	 * @param preservePerimeter whether to preserve the perimeter of the input
   377→	 *                          triangulation; when true, retains edges that lie on
   378→	 *                          the perimeter of the triangulation mesh that would
   379→	 *                          have otherwise been removed (this results in some
   380→	 *                          triangles being included in the output).
   381→	 * @return a GROUP PShape, where each child shape is one quadrangle
   382→	 * @since 1.2.0
   383→	 */
   384→	public static PShape edgeCollapseQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   385→		/*-
   386→		 * From 'Fast unstructured quadrilateral mesh generation'.
   387→		 * A better coloring approach is given in 'Face coloring in unstructured CFD codes'.
   388→		 * 
   389→		 * First partition the edges of the triangular mesh into three groups such that
   390→		 * no triangle has two edges of the same color (find groups by reducing to a
   391→		 * graph-coloring).
   392→		 * Then obtain an all-quadrilateral mesh by removing all edges of *one* 
   393→		 * particular color.
   394→		 */
   395→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   396→		final AbstractBaseGraph<IQuadEdge, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
   397→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   398→			final IConstraint constraint = t.getContainingRegion();
   399→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   400→				graph.addVertex(t.getEdgeA().getBaseReference());
   401→				graph.addVertex(t.getEdgeB().getBaseReference());
   402→				graph.addVertex(t.getEdgeC().getBaseReference());
   403→
   404→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeB().getBaseReference());
   405→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeC().getBaseReference());
   406→				graph.addEdge(t.getEdgeB().getBaseReference(), t.getEdgeC().getBaseReference());
   407→			}
   408→		});
   409→
   410→		Coloring<IQuadEdge> coloring = new RLFColoring<>(graph).getColoring();
   411→
   412→		final HashSet<IQuadEdge> perimeter = new HashSet<>(triangulation.getPerimeter());
   413→		if (!unconstrained) {
   414→			perimeter.clear(); // clear, the perimeter of constrained tin is unaffected by the constraint
   415→		}
   416→
   417→		final Collection<PEdge> meshEdges = new ArrayList<>();
   418→		coloring.getColors().forEach((edge, color) -> {
   419→			/*
   420→			 * "We can remove the edges of any one of the colors, however a convenient
   421→			 * choice is the one that leaves the fewest number of unmerged boundary
   422→			 * triangles". -- ideal, but not implemented here...
   423→			 */
   424→			// NOTE could now apply Topological optimization, as given in paper.
   425→			if ((color < 2) || (preservePerimeter && (edge.isConstrainedRegionBorder() || perimeter.contains(edge)))) {
   426→				meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   427→			}
   428→		});
   429→
   430→		PShape quads = PGS.polygonizeEdges(meshEdges);
   431→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   432→			return quads;
   433→		} else {
   434→			return removeHoles(quads, triangulation);
   435→		}
   436→	}
   437→
   438→	/**
   439→	 * Generates a quadrangulation from a triangulation by "inverting" triangles
   440→	 * (for each triangle, create edges joining its centroid to each of its
   441→	 * vertices).
   442→	 * <p>
   443→	 * This approach tends to create a denser quad mesh than
   444→	 * {@link #edgeCollapseQuadrangulation(IIncrementalTin, boolean)
   445→	 * <code>edgeCollapseQuadrangulation()</code>} on the same input.
   446→	 * 
   447→	 * @param triangulation     a triangulation mesh
   448→	 * @param preservePerimeter whether to preserve the perimeter of the input
   449→	 *                          triangulation; when true, retains edges that lie on
   450→	 *                          the perimeter of the triangulation mesh that would
   451→	 *                          have otherwise been removed (this results in some
   452→	 *                          triangles being included in the output).
   453→	 * @return a GROUP PShape, where each child shape is one quadrangle
   454→	 * @since 1.2.0
   455→	 */
   456→	public static PShape centroidQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   457→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   458→		final HashSet<PEdge> edges = new HashSet<>();
   459→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   460→			final IConstraint constraint = t.getContainingRegion();
   461→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   462→				Vertex centroid = centroid(t);
   463→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexA().x, t.getVertexA().y));
   464→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexB().x, t.getVertexB().y));
   465→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexC().x, t.getVertexC().y));
   466→			}
   467→		});
   468→
   469→		if (preservePerimeter) {
   470→			List<IQuadEdge> perimeter = triangulation.getPerimeter();
   471→			triangulation.edges().forEach(edge -> {
   472→				if (edge.isConstrainedRegionBorder() || (unconstrained && perimeter.contains(edge))) {
   473→					edges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   474→				}
   475→			});
   476→		}
   477→
   478→		final PShape quads = PGS.polygonizeEdges(edges);
   479→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   480→			return quads;
   481→		} else {
   482→			return removeHoles(quads, triangulation);
   483→		}
   484→	}
   485→
   486→	/**
   487→	 * Removes (what should be) holes from a polygonized quadrangulation.
   488→	 * <p>
   489→	 * When the polygonizer is applied to the collapsed triangles of a
   490→	 * triangulation, it cannot determine which collapsed regions represent holes in
   491→	 * the quadrangulation and will consequently fill them in. The subroutine below
   492→	 * restores holes/topology, detecting which polygonized face(s) are original
   493→	 * holes. Note the geometry of the original hole/constraint and its associated
   494→	 * polygonized face are different, since quads are polygonized, not triangles
   495→	 * (hence an overlap metric is used to match candidates).
   496→	 * 
   497→	 * @param faces         faces of the quadrangulation
   498→	 * @param triangulation
   499→	 * @return
   500→	 */
   501→	private static PShape removeHoles(PShape faces, IIncrementalTin triangulation) {
   502→		List<IConstraint> holes = new ArrayList<>(triangulation.getConstraints()); // copy list
   503→		holes = holes.subList(1, holes.size()); // slice off perimeter constraint (not a hole)
   504→
   505→		STRtree tree = new STRtree();
   506→		holes.stream().map(constraint -> constraint.getVertices()).iterator().forEachRemaining(vertices -> {
   507→			CoordinateList coords = new CoordinateList(); // coords of constraint
   508→			vertices.forEach(v -> coords.add(new Coordinate(v.x, v.y)));
   509→			coords.closeRing();
   510→
   511→			if (!Orientation.isCCWArea(coords.toCoordinateArray())) { // triangulation holes are CW
   512→				Polygon polygon = PGS.GEOM_FACTORY.createPolygon(coords.toCoordinateArray());
   513→				tree.insert(polygon.getEnvelopeInternal(), polygon);
   514→			}
   515→		});
   516→
   517→		List<PShape> nonHoles = PGS_Conversion.getChildren(faces).parallelStream().filter(quad -> {
   518→			/*
   519→			 * If quad overlaps with a hole detect whether it *is* that hole via Hausdorff
   520→			 * Similarity.
   521→			 */
   522→			final Geometry g = PGS_Conversion.fromPShape(quad);
   523→
   524→			@SuppressWarnings("unchecked")
   525→			List<Polygon> matches = tree.query(g.getEnvelopeInternal());
   526→
   527→			for (Polygon m : matches) {
   528→				try {
   529→					// PGS_ShapePredicates.overlap() inlined here
   530→					Geometry overlap = OverlayNG.overlay(m, g, OverlayNG.INTERSECTION);
   531→					double a1 = g.getArea();
   532→					double a2 = m.getArea();
   533→					double total = a1 + a2;
   534→					double aOverlap = overlap.getArea();
   535→					double w1 = a1 / total;
   536→					double w2 = a2 / total;
   537→
   538→					double similarity = w1 * (aOverlap / a1) + w2 * (aOverlap / a2);
   539→					if (similarity > 0.2) { // magic constant, unsure what the best value is
   540→						return false; // is hole; keep=false
   541→					}
   542→				} catch (Exception e) { // catch occasional noded error
   543→					continue;
   544→				}
   545→
   546→			}
   547→			return true; // is not hole; keep=true
   548→		}).collect(Collectors.toList());
   549→
   550→		return PGS_Conversion.flatten(nonHoles);
   551→	}
