   553→	/**
   554→	 * Produces a quadrangulation from a point set. The resulting quadrangulation
   555→	 * has a characteristic spiral pattern.
   556→	 * 
   557→	 * @param points
   558→	 * @return a GROUP PShape where each child shape is a single face
   559→	 * @since 1.2.0
   560→	 */
   561→	public static PShape spiralQuadrangulation(List<PVector> points) {
   562→		SpiralQuadrangulation sq = new SpiralQuadrangulation(points);
   563→		return PGS.polygonizeEdges(sq.getQuadrangulationEdges());
   564→	}
