   566→	/**
   567→	 * Transforms a non-conforming mesh shape into a <i>conforming mesh</i> by
   568→	 * performing a "noding" operation. "noding" refers to the process of splitting
   569→	 * edges into two at points where they intersect or touch another edge. It is a
   570→	 * way of ensuring consistency and accuracy in the spatial topology of the mesh.
   571→	 * 
   572→	 * @param shape a GROUP PShape which represents a mesh-like shape, but one that
   573→	 *              isn't conforming (i.e. adjacent edges do not necessarily have
   574→	 *              identical start and end coordinates)
   575→	 * @return the input shape, having been noded and polygonized
   576→	 * @since <code>public</code> since 1.4.0
   577→	 */
   578→	public static PShape nodeNonMesh(PShape shape) {
   579→		final List<SegmentString> segmentStrings = new ArrayList<>(shape.getChildCount() * 3);
   580→
   581→		for (PShape face : shape.getChildren()) {
   582→			for (int i = 0; i < face.getVertexCount(); i++) {
   583→				final PVector a = face.getVertex(i);
   584→				final PVector b = face.getVertex((i + 1) % face.getVertexCount());
   585→				if (!a.equals(b)) {
   586→					segmentStrings.add(PGS.createSegmentString(a, b));
   587→				}
   588→			}
   589→		}
   590→		return PGS.polygonizeSegments(segmentStrings, true);
   591→	}
   592→
   593→	/**
   594→	 * Randomly merges together / dissolves adjacent faces of a mesh.
   595→	 * <p>
   596→	 * The procedure randomly assigns a integer ID to each face and then groups of
   597→	 * mutually adjacent faces that share an ID (belong to the same group) are
   598→	 * merged into one.
   599→	 * 
   600→	 * @param mesh     the conforming mesh shape to perform the operation on
   601→	 * @param nClasses the number of classes to assign to mesh faces; fewer classes
   602→	 *                 means adjacent faces are more likely to share a class and be
   603→	 *                 merged.
   604→	 * @param seed     the seed for the random number generator
   605→	 * @return a new GROUP PShape representing the result of the operation
   606→	 * @since 1.4.0
   607→	 */
   608→	public static PShape stochasticMerge(PShape mesh, int nClasses, long seed) {
   609→		final RandomGenerator random = new XoRoShiRo128PlusRandomGenerator(seed);
   610→		SimpleGraph<PShape, DefaultEdge> graph = PGS_Conversion.toDualGraph(mesh);
   611→		Map<PShape, Integer> classes = new HashMap<>();
   612→		graph.vertexSet().forEach(v -> classes.put(v, random.nextInt(Math.max(nClasses, 1))));
   613→
   614→		/*
   615→		 * Handle "island" faces, which are faces whose neighbours all have the same
   616→		 * class (which differ from the island itself).
   617→		 */
   618→		NeighborCache<PShape, DefaultEdge> cache = new NeighborCache<>(graph);
   619→		graph.vertexSet().forEach(v -> {
   620→			final int vClass = classes.get(v);
   621→			List<PShape> neighbours = cache.neighborListOf(v);
   622→			final int nClass1 = classes.get(neighbours.get(0));
   623→			if (vClass == nClass1) {
   624→				return; // certainly not an island
   625→			}
   626→
   627→			neighbours.removeIf(n -> classes.get(n) == nClass1);
   628→			if (neighbours.isEmpty()) {
   629→				classes.put(v, nClass1); // reassign face class
   630→			}
   631→		});
   632→
   633→		List<DefaultEdge> toRemove = new ArrayList<>();
   634→		graph.edgeSet().forEach(e -> {
   635→			PShape a = graph.getEdgeSource(e);
   636→			PShape b = graph.getEdgeTarget(e);
   637→			if (!classes.get(a).equals(classes.get(b))) {
   638→				toRemove.add(e);
   639→			}
   640→		});
   641→		graph.removeAllEdges(toRemove);
   642→		ConnectivityInspector<PShape, DefaultEdge> ci = new ConnectivityInspector<>(graph);
   643→
   644→		List<PShape> blobs = ci.connectedSets().stream().map(group -> PGS_ShapeBoolean.unionMesh(PGS_Conversion.flatten(group)))
   645→				.collect(Collectors.toList());
   646→		return PGS_Conversion.flatten(blobs);
   647→	}
   648→
   649→	/**
   650→	 * Smoothes a mesh via iterative weighted <i>Laplacian smoothing</i>. The effect
   651→	 * of which is mesh faces become more uniform in size and shape (isotropic).
   652→	 * <p>
   653→	 * In Laplacian smoothing, vertices are replaced with the (weighted) average of
   654→	 * the positions of their adjacent vertices; it is computationally inexpensive
   655→	 * and fairly effective (faces become more isotropic), but it does not guarantee
   656→	 * improvement in element quality.
   657→	 * <p>
   658→	 * Meshes with more faces take more iterations to converge to stable point.
   659→	 * Meshes with highly convex faces may result in issues.
   660→	 * 
   661→	 * @param mesh              a GROUP PShape where each child shape is a single
   662→	 *                          face comprising a conforming mesh
   663→	 * @param iterations        number of smoothing passes to perform. Most meshes
   664→	 *                          will converge very well by around 50-100 passes.
   665→	 * @param preservePerimeter boolean flag to exclude the boundary vertices from
   666→	 *                          being smoothed (thus preserving the mesh perimeter).
   667→	 *                          Generally this should be set to true, otherwise the
   668→	 *                          mesh will shrink as it is smoothed.
   669→	 * @return the smoothed mesh
   670→	 * @since 1.4.0
   671→	 */
   672→	public static PShape smoothMesh(PShape mesh, int iterations, boolean preservePerimeter) {
   673→		PMesh m = new PMesh(mesh);
   674→		for (int i = 0; i < iterations; i++) {
   675→			m.smoothWeighted(preservePerimeter);
   676→		}
   677→		return m.getMesh();
   678→	}
   679→
   680→	/**
   681→	 * Smoothes a mesh via iterative weighted <i>Laplacian smoothing</i>. The effect
   682→	 * of which is mesh faces become more uniform in size and shape (isotropic).
   683→	 * <p>
   684→	 * This particular method iteratively smoothes the mesh until the displacement
   685→	 * value of the most displaced vertex in the prior iteration is less than
   686→	 * <code>displacementCutoff</code>.
   687→	 * <p>
   688→	 * In Laplacian smoothing, vertices are replaced with the (weighted) average of
   689→	 * the positions of their adjacent vertices; it is computationally inexpensive
   690→	 * and fairly effective (faces become more isotropic), but it does not guarantee
   691→	 * improvement in element quality.
   692→	 * <p>
   693→	 * Meshes with more faces take more iterations to converge to stable point.
   694→	 * Meshes with highly convex faces may result in issues.
   695→	 * 
   696→	 * @param mesh               a GROUP PShape where each child shape is a single
   697→	 *                           face comprising a conforming mesh.
   698→	 * @param displacementCutoff the displacement threshold of the most displaced
   699→	 *                           vertex in a single iteration to stop the iterative
   700→	 *                           smoothing.
   701→	 * @param preservePerimeter  boolean flag to exclude the boundary vertices from
   702→	 *                           being smoothed (thus preserving the mesh
   703→	 *                           perimeter). Generally this should be set to true,
   704→	 *                           otherwise the mesh will shrink as it is smoothed.
   705→	 * @return the smoothed mesh
   706→	 * @since 1.4.0
   707→	 */
   708→	public static PShape smoothMesh(PShape mesh, double displacementCutoff, boolean preservePerimeter) {
   709→		displacementCutoff = Math.max(displacementCutoff, 1e-3);
   710→		PMesh m = new PMesh(mesh);
   711→
   712→		double displacement;
   713→		do {
   714→			displacement = m.smoothWeighted(preservePerimeter);
   715→		} while (displacement > displacementCutoff);
   716→		return m.getMesh();
   717→	}
   718→
   719→	/**
   720→	 * Simplifies the boundaries of the faces in a mesh while preserving the
   721→	 * original mesh topology.
   722→	 * 
   723→	 * @param mesh              GROUP shape comprising the faces of a conforming
   724→	 *                          mesh
   725→	 * @param tolerance         the simplification tolerance for area-based
   726→	 *                          simplification. Roughly equal to the maximum
   727→	 *                          distance by which a simplified line can change from
   728→	 *                          the original.
   729→	 * @param preservePerimeter whether to only simplify inner-boundaries and
   730→	 *                          leaving outer boundary edges unchanged.
   731→	 * @return GROUP shape comprising the simplfied mesh faces
   732→	 * @since 1.4.0
   733→	 */
   734→	public static PShape simplifyMesh(PShape mesh, double tolerance, boolean preservePerimeter) {
   735→		Geometry[] geometries = PGS_Conversion.getChildren(mesh).stream().map(s -> PGS_Conversion.fromPShape(s)).toArray(Geometry[]::new);
   736→		CoverageSimplifier simplifier = new CoverageSimplifier(geometries);
   737→		Geometry[] output;
   738→		if (preservePerimeter) {
   739→			output = simplifier.simplifyInner(tolerance);
   740→		} else {
   741→			output = simplifier.simplify(tolerance);
   742→		}
   743→		return PGS_Conversion.toPShape(Arrays.asList(output));
   744→	}
   745→
   746→	/**
   747→	 * Extracts all inner edges from a mesh. Inner edges consist only of edges that
   748→	 * are shared by adjacent faces, and not edges comprising the mesh boundary nor
   749→	 * edges comprising holes within faces.
   750→	 * 
   751→	 * @param mesh The conforming mesh shape to extract inner edges from.
   752→	 * @return A shape representing the dissolved linework of inner mesh edges.
   753→	 * @since 1.4.0
   754→	 */
   755→	public static PShape extractInnerEdges(PShape mesh) {
   756→		List<PEdge> edges = PGS_SegmentSet.fromPShape(mesh);
   757→		Map<PEdge, Integer> bag = new HashMap<>(edges.size());
   758→		edges.forEach(edge -> {
   759→			bag.merge(edge, 1, Integer::sum);
   760→		});
   761→
   762→		List<PEdge> innerEdges = bag.entrySet().stream().filter(e -> e.getValue() > 1).map(e -> e.getKey()).collect(Collectors.toList());
   763→		return PGS_SegmentSet.dissolve(innerEdges);
   764→	}
