   766→	/**
   767→	 * Recursively merges smaller faces of a mesh into their adjacent faces. The
   768→	 * procedure continues until there are no resulting faces with an area smaller
   769→	 * than the specified threshold.
   770→	 * 
   771→	 * @param mesh          a GROUP shape representing a conforming mesh the mesh to
   772→	 *                      perform area merging on
   773→	 * @param areaThreshold The maximum permissible area threshold for merging
   774→	 *                      faces. Any faces smaller than this threshold will be
   775→	 *                      consolidated into their neighboring faces.
   776→	 * @return GROUP shape comprising the merged mesh faces
   777→	 * @since 1.4.0
   778→	 */
   779→	public static PShape areaMerge(PShape mesh, double areaThreshold) {
   780→		PShape merged = AreaMerge.areaMerge(mesh, areaThreshold);
   781→		return merged;
   782→	}
