   784→	/**
   785→	 * Splits each edge of a given mesh shape into a specified number of
   786→	 * equal-length parts and creates a new shape from the resulting smaller edges.
   787→	 * This method preserves the overall topology of the original mesh.
   788→	 * 
   789→	 * @param split The PShape representing a polygon to be split into smaller
   790→	 *              edges.
   791→	 * @param parts The number of equal parts each edge of the polygon should be
   792→	 *              split into. Should be a positive integer, but if less than 1,
   793→	 *              it's reset to 1.
   794→	 * @return A new mesh PShape created from the split edges.
   795→	 * @since 1.4.0
   796→	 */
   797→	public static PShape splitEdges(PShape split, int parts) {
   798→		parts = Math.max(1, parts);
   799→		HashSet<PEdge> edges = new HashSet<>(PGS_SegmentSet.fromPShape(split));
   800→		List<PEdge> splitEdges = new ArrayList<>(edges.size() * parts);
   801→
   802→		for (PEdge edge : edges) {
   803→			double from = 0;
   804→			double step = 1.0 / parts;
   805→			for (int i = 0; i < parts; i++) {
   806→				double to = from + step;
   807→				PEdge subEdge = edge.slice(from, to);
   808→				splitEdges.add(subEdge);
   809→				from = to;
   810→			}
   811→		}
   812→
   813→		return PGS.polygonizeEdges(splitEdges);
   814→	}
   815→
   816→	/**
   817→	 * Calculate the longest edge of a given triangle.
   818→	 */
   819→	private static IQuadEdge findLongestEdge(final SimpleTriangle t) {
   820→		if (t.getEdgeA().getLength() > t.getEdgeB().getLength()) {
   821→			if (t.getEdgeC().getLength() > t.getEdgeA().getLength()) {
   822→				return t.getEdgeC();
   823→			} else {
   824→				return t.getEdgeA();
   825→			}
   826→		} else {
   827→			if (t.getEdgeC().getLength() > t.getEdgeB().getLength()) {
   828→				return t.getEdgeC();
   829→			} else {
   830→				return t.getEdgeB();
   831→			}
   832→		}
   833→	}
   834→
   835→	private static double[] midpoint(final IQuadEdge edge) {
   836→		final Vertex a = edge.getA();
   837→		final Vertex b = edge.getB();
   838→		return new double[] { (a.x + b.x) / 2d, (a.y + b.y) / 2d };
   839→	}
   840→
   841→	private static Vertex centroid(final SimpleTriangle t) {
   842→		final Vertex a = t.getVertexA();
   843→		final Vertex b = t.getVertexB();
   844→		final Vertex c = t.getVertexC();
   845→		double x = a.x + b.x + c.x;
   846→		x /= 3;
   847→		double y = a.y + b.y + c.y;
   848→		y /= 3;
   849→		return new Vertex(x, y, 0);
   850→	}
   851→
   852→}
