   802→		for (PEdge edge : edges) {
   803→			double from = 0;
   804→			double step = 1.0 / parts;
   805→			for (int i = 0; i < parts; i++) {
   806→				double to = from + step;
   807→				PEdge subEdge = edge.slice(from, to);
   808→				splitEdges.add(subEdge);
   809→				from = to;
   810→			}
   811→		}
   812→
