   819→	private static IQuadEdge findLongestEdge(final SimpleTriangle t) {
   820→		if (t.getEdgeA().getLength() > t.getEdgeB().getLength()) {
   821→			if (t.getEdgeC().getLength() > t.getEdgeA().getLength()) {
   822→				return t.getEdgeC();
   823→			} else {
   824→				return t.getEdgeA();
   825→			}
   826→		} else {
   827→			if (t.getEdgeC().getLength() > t.getEdgeB().getLength()) {
   828→				return t.getEdgeC();
   829→			} else {
   830→				return t.getEdgeB();
   831→			}
   832→		}
   833→	}
