   836→		final Vertex a = edge.getA();
   837→		final Vertex b = edge.getB();
   838→		return new double[] { (a.x + b.x) / 2d, (a.y + b.y) / 2d };
   839→	}
   840→
   841→	private static Vertex centroid(final SimpleTriangle t) {
   842→		final Vertex a = t.getVertexA();
   843→		final Vertex b = t.getVertexB();
   844→		final Vertex c = t.getVertexC();
   845→		double x = a.x + b.x + c.x;
   846→		x /= 3;
   847→		double y = a.y + b.y + c.y;
   848→		y /= 3;
   849→		return new Vertex(x, y, 0);
   850→	}
