    18→package org.tinspin.index.kdtree;
    19→
    20→import java.util.*;
    21→import java.util.function.Predicate;
    22→
    23→import org.tinspin.index.*;
    24→import org.tinspin.index.util.MutableRef;
    25→import org.tinspin.index.util.StringBuilderLn;
    26→
    27→/**
    28→ * A simple KD-Tree implementation. 
    29→ * 
    30→ * @author T. Zäschke
    31→ *
    32→ * @param <T> Value type
    33→ */
    34→public class KDTree<T> implements PointMap<T>, PointMultimap<T> {
    35→
    36→	public static final boolean DEBUG = false;
    37→
    38→	private final int dims;
    39→	/** Defensive keys copying. If `false`, the kd-tree will store the passed in
    40→	 * double[] keys internally (this reduces required memory).
    41→	 * If `true`, the keys are copied in order to avoid accidental modification. */
    42→	private final boolean defensiveKeyCopy;
    43→	private int size = 0;
    44→	private int modCount = 0;
    45→	private long nDist1NN = 0;
    46→	private long nDistKNN = 0;
    47→	//During insertion, the tree maintains an invariant that if two points have the
    48→	//same value in any dimension, then one key is never in the 'lower' branch of the other.
    49→	//This allows very efficient look-up because we have to follow only a single path.
    50→	//Unfortunately, removing keys (and moving up keys in the tree) may break this invariant.
    51→	//
    52→	//The cost of breaking the invariant is that there may be two branches that contain the same
    53→	//key. This makes searches more expensive simply because the code gets more complex.
    54→	//
    55→	//One solution to maintain the invariant is to repair the invariant by moving all points 
    56→	//with the same value into the 'upper' part of the point that was moved up. 
    57→	//Identifying these points is relatively cheap, we can do this while searching for 
    58→	//the min/max during removal. However, _moving_ these point may be very expensive.
    59→	//
    60→	//Our (pragmatic) solution is to identify when the invariant gets broken.
    61→	//When it is not broken, we use the simple search. If it gets broken, we use the slower search.
    62→	//This is especially useful in scenarios where 'remove()' is not required or where
    63→	//points have never the same values (such as for physical measurements or other experimental results).
    64→	private boolean invariantBroken = false;
    65→
    66→	private Node<T> root;
    67→
    68→
    69→	private KDTree(int dims, boolean defensiveKeyCopy) {
    70→		if (DEBUG) {
    71→			System.err.println("Warning: DEBUG enabled");
    72→		}
    73→		this.dims = dims;
    74→		this.defensiveKeyCopy = defensiveKeyCopy;
    75→	}
    76→
    77→	public static <T> KDTree<T> create(int dims) {
    78→		return new KDTree<>(dims, true);
    79→	}
    80→
    81→	public static <T> KDTree<T> create(IndexConfig config) {
    82→		return new KDTree<>(config.getDimensions(), config.getDefensiveKeyCopy());
    83→	}
    84→
    85→	/**
    86→	 * Insert a key-value pair.
    87→	 *
    88→	 * @param key   the key
    89→	 * @param value the value
    90→	 */
    91→	@Override
    92→	public void insert(double[] key, T value) {
    93→		size++;
    94→		modCount++;
    95→		if (root == null) {
    96→			root = new Node<>(key, value, 0, defensiveKeyCopy);
    97→			return;
    98→		}
    99→		Node<T> n = root;
   100→		while ((n = n.getClosestNodeOrAddPoint(key, value, dims, defensiveKeyCopy)) != null) ;
   101→	}
   102→
   103→	/**
   104→	 * Check whether a given key exists.
   105→	 *
   106→	 * @param key the key to check
   107→	 * @return true iff the key exists
   108→	 */
   109→	public boolean contains(double[] key) {
   110→		return findNodeExact(key, new RemoveResult<>(), e -> true) != null;
   111→	}
   112→
   113→	/**
   114→	 * Lookup an entry, using exact match.
   115→	 *
   116→	 * @param point the point
   117→	 * @return an iterator over all entries at the given point
   118→	 */
   119→	@Override
   120→	public KDIterator<T> queryExactPoint(double[] point) {
   121→		return query(point, point);
   122→	}
   123→
   124→	/**
   125→	 * Get the value associates with the key.
   126→	 *
   127→	 * @param key the key to look up
   128→	 * @return the value for the key or 'null' if the key was not found
   129→	 */
   130→	@Override
