   136→	private Node<T> findNodeExact(double[] key, RemoveResult<T> resultDepth, Predicate<PointEntry<T>> filter) {
   137→		if (root == null) {
   138→			return null;
   139→		}
   140→		return invariantBroken
   141→				? findNodeExactSlow(key, root, null, resultDepth, filter)
   142→				: findNodeExactFast(key, null, resultDepth, filter);
