   145→	private Node<T> findNodeExactFast(double[] key, Node<T> parent, RemoveResult<T> resultDepth, Predicate<PointEntry<T>> filter) {
   146→		Node<T> n = root;
   147→		do {
   148→			double[] nodeKey = n.point();
   149→			double nodeX = nodeKey[n.getDim()];
   150→			double keyX = key[n.getDim()];
   151→			if (keyX == nodeX && Arrays.equals(key, nodeKey) && filter.test(n)) {
   152→				resultDepth.pos = n.getDim();
   153→				resultDepth.nodeParent = parent;
   154→				return n;
   155→			}
   156→			parent = n;
   157→			n = (keyX >= nodeX) ? n.getHi() : n.getLo();
   158→		} while (n != null);
   159→		return n;
   160→	}
