   162→	private Node<T> findNodeExactSlow(double[] key, Node<T> n, Node<T> parent, RemoveResult<T> resultDepth, Predicate<PointEntry<T>> filter) {
   163→		do {
   164→			double[] nodeKey = n.point();
   165→			double nodeX = nodeKey[n.getDim()];
   166→			double keyX = key[n.getDim()];
   167→			if (keyX == nodeX) {
   168→				if (Arrays.equals(key, nodeKey) && filter.test(n)) {
   169→					resultDepth.pos = n.getDim();
   170→					resultDepth.nodeParent = parent;
   171→					return n;
   172→				}
   173→				//Broken invariant? We need to check the 'lower' part as well...
   174→				if (n.getLo() != null) {
   175→					Node<T> n2 = findNodeExactSlow(key, n.getLo(), n, resultDepth, filter);
   176→					if (n2 != null) {
   177→						return n2;
   178→					}
   179→				}
   180→			}
   181→			parent = n;
   182→			n = (keyX >= nodeX) ? n.getHi() : n.getLo();
   183→		} while (n != null);
   184→		return n;
   185→	}
