   213→	@Override
   214→	public boolean removeIf(double[] key, Predicate<PointEntry<T>> pred) {
   215→		if (root == null) {
   216→			return false;
   217→		}
   218→
   219→		invariantBroken = true;
   220→
   221→		//find
   222→		RemoveResult<T> removeResult = new RemoveResult<>();
   223→		Node<T> eToRemove = findNodeExact(key, removeResult, pred);
   224→		if (eToRemove == null) {
   225→			return false;
   226→		}
   227→
   228→		//remove
   229→		modCount++;
   230→		T value = eToRemove.value();
   231→		if (eToRemove == root && size == 1) {
   232→			root = null;
   233→			size = 0;
   234→			invariantBroken = false;
   235→			return true;
   236→		}
   237→		
   238→		// find replacement
   239→		while (eToRemove != null && !eToRemove.isLeaf()) {
   240→			//recurse
   241→			int pos = removeResult.pos;
   242→			removeResult.node = null; 
   243→			//randomize search direction (modCount)
   244→//			if (((modCount & 0x1) == 0 || eToRemove.getHi() == null) && eToRemove.getLo() != null) {
   245→//				//get replacement from left
   246→//				removeResult.best = Double.NEGATIVE_INFINITY;
   247→//				removeMaxLeaf(eToRemove.getLo(), eToRemove, pos, removeResult);
   248→//			} else if (eToRemove.getHi() != null) {
   249→//				//get replacement from right
   250→//				removeResult.best = Double.POSITIVE_INFINITY;
   251→//				removeMinLeaf(eToRemove.getHi(), eToRemove, pos, removeResult);
   252→//			}
   253→			if (eToRemove.getHi() != null) {
   254→				//get replacement from right
   255→				//This is preferable, because it cannot break the invariant
   256→				removeResult.best = Double.POSITIVE_INFINITY;
   257→				removeMinLeaf(eToRemove.getHi(), eToRemove, pos, removeResult);
   258→			} else if (eToRemove.getLo() != null) {
   259→				//get replacement from left
   260→				removeResult.best = Double.NEGATIVE_INFINITY;
   261→				removeMaxLeaf(eToRemove.getLo(), eToRemove, pos, removeResult);
   262→			}
   263→			eToRemove.set(removeResult.node.point(), removeResult.node.value());
   264→			eToRemove = removeResult.node;
   265→		} 
   266→		//leaf node
   267→		Node<T> parent = removeResult.nodeParent; 
   268→		if (parent != null) {
   269→			if (parent.getLo() == eToRemove) {
   270→				parent.setLeft(null);
   271→			} else if (parent.getHi() == eToRemove) {
   272→				parent.setRight(null);
   273→			} else { 
   274→				throw new IllegalStateException();
   275→			}
   276→		}
   277→		size--;
   278→		return true;
   279→	}
