   288→	private void removeMinLeaf(Node<T> node, Node<T> parent, int pos, RemoveResult<T> result) {
   289→		//Split in 'interesting' dimension
   290→		if (pos == node.getDim()) {
   291→			//We strictly look for leaf nodes with left==null
   292→			// -> left!=null means the left child is at least as small as the current node
   293→			if (node.getLo() != null) {
   294→				removeMinLeaf(node.getLo(), node, pos, result);
   295→			} else if (node.point()[pos] <= result.best) {
   296→				result.node = node;
   297→				result.nodeParent = parent;
   298→				result.best = node.point()[pos];
   299→				result.pos = node.getDim();
   300→			}
   301→		} else {
   302→			//split in any other dimension.
   303→			//First, check local key. 
   304→			double localX = node.point()[pos];
   305→			if (localX <= result.best) {
   306→				result.node = node;
   307→				result.nodeParent = parent;
   308→				result.best = localX;
   309→				result.pos = node.getDim();
   310→			}
   311→			if (node.getLo() != null) {
   312→				removeMinLeaf(node.getLo(), node, pos, result);
   313→			}
   314→			if (node.getHi() != null) {
   315→				removeMinLeaf(node.getHi(), node, pos, result);
   316→			}
   317→		}
   318→	}
