   320→	private void removeMaxLeaf(Node<T> node, Node<T> parent, int pos, RemoveResult<T> result) {
   321→		//Split in 'interesting' dimension
   322→		if (pos == node.getDim()) {
   323→			//We strictly look for leaf nodes with left==null
   324→			if (node.getHi() != null) {
   325→				removeMaxLeaf(node.getHi(), node, pos, result);
   326→			} else if (node.point()[pos] >= result.best) {
   327→				result.node = node;
   328→				result.nodeParent = parent;
   329→				result.best = node.point()[pos];
   330→				result.pos = node.getDim();
   331→			}
   332→		} else {
   333→			//split in any other dimension.
   334→			//First, check local key. 
   335→			double localX = node.point()[pos];
   336→			if (localX >= result.best) {
   337→				result.node = node;
   338→				result.nodeParent = parent;
   339→				result.best = localX;
   340→				result.pos = node.getDim();
   341→			}
   342→			if (node.getLo() != null) {
   343→				removeMaxLeaf(node.getLo(), node, pos, result);
   344→			}
   345→			if (node.getHi() != null) {
   346→				 removeMaxLeaf(node.getHi(), node, pos, result);
   347→			}
   348→		}
   349→	}
