   435→	private List<PointEntryKnn<T>> knnQuery(double[] center, int k, PointDistance distFn) {
   436→		if (root == null) {
   437→			return Collections.emptyList();
   438→		}
   439→		ArrayList<PointEntryKnn<T>> candidates = new ArrayList<>(k);
   440→		rangeSearchKNN(root, center, candidates, k, Double.POSITIVE_INFINITY, distFn);
   441→		return candidates;
