   444→	private double rangeSearchKNN(Node<T> node, double[] center,
   445→                                  ArrayList<PointEntryKnn<T>> candidates, int k, double maxRange, PointDistance distFn) {
   446→    	int pos = node.getDim();
   447→    	if (node.getLo() != null && (center[pos] < node.point()[pos] || node.getHi() == null)) {
   448→        	//go down
   449→    		maxRange = rangeSearchKNN(node.getLo(), center, candidates, k, maxRange, distFn);
   450→        	//refine result
   451→    		if (center[pos] + maxRange >= node.point()[pos]) {
   452→    			maxRange = addCandidate(node, center, candidates, k, maxRange, distFn);
   453→        		if (node.getHi() != null) {
   454→        			maxRange = rangeSearchKNN(node.getHi(), center, candidates, k, maxRange, distFn);
   455→        		}
   456→    		}
   457→    	} else if (node.getHi() != null) {
   458→        	//go down
   459→    		maxRange = rangeSearchKNN(node.getHi(), center, candidates, k, maxRange, distFn);
   460→        	//refine result
   461→    		if (center[pos] <= node.point()[pos] + maxRange) {
   462→    			maxRange = addCandidate(node, center, candidates, k, maxRange, distFn);
   463→        		if (node.getLo() != null) {
   464→        			maxRange = rangeSearchKNN(node.getLo(), center, candidates, k, maxRange, distFn);
   465→        		}
   466→    		}
   467→    	} else {
   468→    		//leaf -> first (probably best) match!
   469→    		maxRange = addCandidate(node, center, candidates, k, maxRange, distFn);
   470→    	}
   471→    	return maxRange;
   472→    }
