   475→    private static final Comparator<PointEntryKnn<?>> compKnn =
   476→    		(PointEntryKnn<?> point1, PointEntryKnn<?> point2) -> {
   477→    			double deltaDist = point1.dist() - point2.dist();
   478→    			return deltaDist < 0 ? -1 : (deltaDist > 0 ? 1 : 0);
   479→    		};
