   481→    
   482→    private double addCandidate(Node<T> node, double[] center,
   483→                                ArrayList<PointEntryKnn<T>> candidates, int k, double maxRange, PointDistance distFn) {
   484→    	nDistKNN++;
   485→    	//add ?
   486→    	double dist = distFn.dist(center, node.point());
   487→    	if (dist > maxRange) {
   488→    		//don't add if too far away
   489→    		return maxRange;
   490→    	}
   491→    	if (dist == maxRange && candidates.size() >= k) {
   492→    		//don't add if we already have enough equally good results.
   493→    		return maxRange;
   494→    	}
   495→		PointEntryKnn<T> cand;
   496→    	if (candidates.size() >= k) {
   497→    		cand = candidates.remove(k - 1);
   498→    		cand.set(node, dist);
   499→    	} else {
   500→    		cand = new PointEntryKnn<>(node, dist);
   501→    	}
   502→    	int insertionPos = Collections.binarySearch(candidates, cand, compKnn);
   503→    	insertionPos = insertionPos >= 0 ? insertionPos : -(insertionPos+1);
   504→    	candidates.add(insertionPos, cand);
   505→    	return candidates.size() < k ? maxRange : candidates.get(candidates.size() - 1).dist();
   506→    }
