   502→    	int insertionPos = Collections.binarySearch(candidates, cand, compKnn);
   503→    	insertionPos = insertionPos >= 0 ? insertionPos : -(insertionPos+1);
   504→    	candidates.add(insertionPos, cand);
   505→    	return candidates.size() < k ? maxRange : candidates.get(candidates.size() - 1).dist();
   506→    }
   507→
   508→
   509→    private static class KDQueryIteratorKnn<T> implements PointIteratorKnn<T> {
   510→
   511→    	private Iterator<PointEntryKnn<T>> it;
   512→    	private final KDTree<T> tree;
   513→		private final PointDistance distFn;
   514→
   515→		public KDQueryIteratorKnn(KDTree<T> tree, double[] center, int k, PointDistance distFn) {
   516→			this.tree = tree;
   517→			this.distFn = distFn;
   518→			reset(center, k);
   519→		}
   520→
   521→		@Override
   522→		public boolean hasNext() {
   523→			return it.hasNext();
   524→		}
   525→
   526→		@Override
   527→		public PointEntryKnn<T> next() {
   528→			return it.next();
   529→		}
   530→
   531→		@Override
   532→		public KDQueryIteratorKnn<T> reset(double[] center, int k) {
   533→			it = tree.knnQuery(center, k, distFn).iterator();
   534→			return this;
   535→		}
   536→    }
   537→    
   538→    /**
   539→	 * Returns a printable list of the tree.
   540→	 * @return the tree as String
   541→	 */
   542→    @Override
   543→	public String toStringTree() {
   544→		StringBuilderLn sb = new StringBuilderLn();
   545→		if (root == null) {
   546→			sb.append("empty tree");
   547→		} else {
   548→			toStringTree(sb, root, 0);
   549→		}
   550→		return sb.toString();
   551→	}
   552→	
   553→	private void toStringTree(StringBuilderLn sb, Node<T> node, int depth) {
   554→		if (node.getLo() != null) {
   555→			toStringTree(sb, node.getLo(), depth+1);
   556→		}
   557→		for (int i = 0; i < depth; i++) {
   558→			sb.append(".");
   559→		}
   560→		sb.append(" ");
   561→		sb.append(Arrays.toString(node.point()));
   562→		sb.append(" v=").append(node.value());
   563→		sb.append(" l/r=");
   564→		sb.append(node.getLo() == null ? null : Arrays.toString(node.getLo().point()));
   565→		sb.append("/");
   566→		sb.append(node.getHi() == null ? null : Arrays.toString(node.getHi().point()));
   567→		sb.appendLn();
   568→		if (node.getHi() != null) {
   569→			toStringTree(sb, node.getHi(), depth+1);
   570→		}
   571→	}
   572→	
   573→	@Override
   574→	public String toString() {
   575→		return "KDTree;size=" + size + 
   576→				";DEBUG=" + DEBUG + 
   577→				";center=" + (root==null ? "null" : Arrays.toString(root.point()));
   578→	}
   579→	
   580→	@Override
   581→	public KDStats getStats() {
   582→		KDStats s = new KDStats(this);
   583→		if (root != null) {
   584→			root.checkNode(s, 0);
   585→		}
   586→		return s;
   587→	}
   588→	
   589→	/**
   590→	 * Statistics container class.
   591→	 */
   592→	public static class KDStats extends Stats {
   593→		public KDStats(KDTree<?> tree) {
   594→			super(tree.nDist1NN + tree.nDistKNN, tree.nDist1NN, tree.nDistKNN);
   595→		}
   596→	}
   597→
   598→	@Override
   599→	public int getDims() {
   600→		return dims;
   601→	}
   602→
   603→	@Override
   604→	public PointIterator<T> iterator() {
   605→		if (root == null) {
   606→			return query(new double[dims], new double[dims]);
   607→		}
   608→		//return query(root.);
   609→		//TODO
   610→		throw new UnsupportedOperationException();
   611→	}
   612→
   613→	@Override
   614→	public PointEntryKnn<T> query1nn(double[] center) {
   615→		return queryKnn(center, 1).next();
   616→	}
   617→
   618→	@Override
   619→	public PointIteratorKnn<T> queryKnn(double[] center, int k) {
   620→		if (size < 1_000_000 && k <= 10) {
   621→			return new KDQueryIteratorKnn<>(this, center, k, PointDistance.L2);
   622→		}
   623→		return new KDIteratorKnn<>(root, k, center, PointDistance.L2, (e, d) -> true);
   624→	}
   625→
   626→	@Override
   627→	public PointIteratorKnn<T> queryKnn(double[] center, int k, PointDistance distFn) {
   628→		// For small trees, the old iterator is about 3x faster.
   629→		// For 1M it is about even, for 10M the new HS-iterator is about 2x faster.
   630→		if (size < 1_000_000 && k <= 10) {
   631→			return new KDQueryIteratorKnn<>(this, center, k, distFn);
   632→		}
   633→		return new KDIteratorKnn<>(root, k, center, distFn, (e, d) -> true);
   634→	}
   635→
   636→	@Override
   637→	public int getNodeCount() {
   638→		return getStats().getNodeCount();
   639→	}
   640→
   641→	@Override
   642→	public int getDepth() {
   643→		return getStats().getMaxDepth();
   644→	}
   645→	
