   496→    	if (candidates.size() >= k) {
   497→    		cand = candidates.remove(k - 1);
   498→    		cand.set(node, dist);
   499→    	} else {
   500→    		cand = new PointEntryKnn<>(node, dist);
   501→    	}
   502→    	int insertionPos = Collections.binarySearch(candidates, cand, compKnn);
   503→    	insertionPos = insertionPos >= 0 ? insertionPos : -(insertionPos+1);
   504→    	candidates.add(insertionPos, cand);
   505→    	return candidates.size() < k ? maxRange : candidates.get(candidates.size() - 1).dist();
   506→    }
