    29→/**
    30→ * A 'faster' CoverTree implementation based on the paper:
    31→ * <p>
    32→ * "Faster Cover Trees", Mike Izbicki, Christian R. Shelton,
    33→ * Proceedings of the 32nd International Conference on Machine Learning,
    34→ * Lille, France, 2015. 
    35→ * <p>
    36→ * Changes over original algorithms:
    37→ *  - findNearestNeighbour compares
    38→ *  	if (d(y, x) greater (d(_x_, q.point()) - q.maxdist(this)))
    39→ *    instead of 
    40→ *      if (d(y, x) greater (d(_y_, q.point()) - q.maxdist(this)))
    41→ *  - maxDist: 
    42→ *    - lazily calculated.
    43→ *    - calculated while excluding subbranches that don't need to be calculated
    44→ *    - Invalidated on modifications (should speed up remove/insert)
    45→ *  - Algorithm 2 (insert) uses BASE=1.3:
    46→ *     BASE*covdist(p)  
    47→ *     instead of
    48→ *     2*covdist(p)) 
    49→ *  - Rebalancing:
    50→ *    - The paper proposes to sort the children on their distance to 'x' and then
    51→ *      insert into the first one that has enough covdist.
    52→ *      The sorting appears unnecessary because we anyway have to check all children,
    53→ *      and finding the closest one is trivially possible without sorting.
    54→ *  - Some optimizations for kNN which are not discussed in the paper
    55→ *  <p>
    56→ * Other:
    57→ * - We also implemented the kNN algorithm by Hjaltason and Samet,
    58→ *   but it about 2x as long as our own algorithm in all scenarios we tested.
    59→ * TODO
    60→ * - Rebalancing (nearest-ancestor)
    61→ * - Merge Node/Point classes
    62→ *     
    63→ * @author Tilmann Zäschke
    64→ */
    65→public class CoverTree<T> implements PointMap<T> {
    66→
    67→	private final int dims;
    68→	private int nEntries;
    69→	
    70→	private Node<T> root = null;
    71→	
    72→	private static final double DEFAULT_BASE = 2.0;
    73→	
    74→	private static final boolean NEAREST_ANCESTOR = true;
    75→	
    76→	private final double BASE;
    77→	private final double LOG_BASE;
    78→	private final PointDistance dist;
    79→	private static final PEComparator comparator = new PEComparator();
    80→	private long nDistCalc = 0;
    81→	private long nDist1NN = 0;
    82→	private long nDistKNN = 0;
    83→	
    84→	private final double log13(double n) {
    85→		//log_b(n) = log_e(n) / log_e(b)
    86→		return Math.log(n) / LOG_BASE;
    87→	}
    88→	
    89→	private CoverTree(int nDims, double base, PointDistance dist) {
    90→		this.dims = nDims;
    91→		this.BASE = base;
    92→		this.LOG_BASE = Math.log(BASE);
    93→		this.dist = dist != null ? dist : PointDistance.L2;
    94→	}
    95→		
    96→	public static <T> PointEntry<T> create(double[] point, T value) {
    97→		return new PointEntry<>(point, value);
    98→	}
    99→
   100→	public static <T> CoverTree<T> create(int nDims) {
   101→		return new CoverTree<>(nDims, DEFAULT_BASE, PointDistance.L2);
   102→	}
   103→	
   104→	public static <T> CoverTree<T> create(int nDims, double base, PointDistance dist) {
   105→		return new CoverTree<>(nDims, base, dist);
   106→	}
   107→	
   108→	public static <T> CoverTree<T> create(PointEntry<T>[] data, double base,
   109→			PointDistance distFn) {
   110→		if (data == null || data.length == 0) {
   111→			throw new IllegalStateException("Bulk load with empty data no possible.");
   112→		}
   113→		CoverTree<T> tree = new CoverTree<>(data[0].point().length, base, distFn);
   114→		if (data.length == 1) {
   115→			tree.root = new Node<>(data[0], 0);
   116→			tree.nEntries++;
   117→			return tree;
   118→		}
   119→		
   120→		//The point of bulk load is (currently) only to initialize the tree with a
   121→		//suitable 'level' and 'root', which should avoid any problems with having 
   122→		//to pull up leaves to replace the root. Bulk loading thus allows a BASE < 2.0 .
   123→		
   124→		PointEntry<T> newRoot = data[0];
   125→		PointEntry<T> mostDistantPoint = data[1];
   126→		double largestDistance = tree.d(newRoot, mostDistantPoint); 
   127→		for (int i = 2; i < data.length; i++) {
   128→			PointEntry<T> x = data[i];
   129→			double dist = tree.d(newRoot, x);
   130→			if (dist > largestDistance) {
   131→				largestDistance = dist;
   132→				mostDistantPoint = x;
   133→			}
   134→		}
   135→		
   136→		int requiredLevel = (int) (tree.log13(largestDistance) + 1);
   137→		tree.root = new Node<>(data[0], requiredLevel);
   138→		//TODO insert farthest point as second point?
   139→		
   140→		for (int i = 1; i < data.length; i++) {
   141→			Node<T> x = new Node<>(data[i], -1);
   142→			tree.insert(tree.root, x);
   143→		}
   144→
   145→		tree.nEntries = data.length;
   146→
   147→		return tree;
   148→	}
