   161→	public void clear() {
   162→		nEntries = 0;
   163→		root = null;
   164→	}
   165→
   166→	@Override
   167→	public CTStats getStats() {
   168→		CTStats stats = new CTStats(this);
   169→		if (root != null) {
   170→			getStats(root, stats);
   171→		}
   172→		return stats;
   173→	}
   174→
   175→	@Override
   176→	public int getNodeCount() {
   177→		//nEntries == nNodes
   178→		return nEntries;
   179→	}
   180→
   181→	@Override
   182→	public int getDepth() {
