   186→		return root.getLevel() - getStats().minLevel;
   187→	}
   188→
   189→	@Override
   190→	public String toStringTree() {
   191→		if (root != null) {
   192→			return toStringTree(new StringBuilder(), root).toString();
   193→		}
   194→		return "";
   195→	}
   196→
   197→	private StringBuilder toStringTree(StringBuilder sb, Node<T> node) {
   198→		toStringNode(sb, node);
   199→		sb.append("\n");
   200→		if (node.hasChildren()) {
   201→			for (Node<T> c : node.getChildren()) {
   202→				toStringTree(sb, c);
   203→			}
   204→		}
   205→		return sb;
   206→	}
   207→	
   208→	private StringBuilder toStringNode(StringBuilder sb, Node<T> node) {
   209→		for (int i = root.getLevel(); i > node.getLevel(); i--) {
   210→			sb.append(".");
   211→		}
   212→		sb.append("L=").append(node.getLevel());
   213→		sb.append(";MaxD=")
   214→		//.append(node.maxdist(this))
   215→		.append("/").append(node.maxdistInternal());
   216→		sb.append(";ParD=").append(node.getDistanceToParent());
   217→		sb.append(";CovD=").append(covdist(node));
   218→		if (node.hasChildren()) {
   219→			sb.append(";nC=").append(node.getChildren().size());
   220→		} else {
   221→			sb.append(";nC=0");
   222→		}
   223→		sb.append(";coord=").append(Arrays.toString(node.point().point()));
   224→		return sb;
   225→	}
   226→	
   227→	@Override
   228→	public void insert(double[] key, T value) {
   229→		//System.out.println("Inserting(" + nEntries + "): " + Arrays.toString(key));
   230→		Node<T> x = new Node<>(new PointEntry<>(key, value), -1);
   231→		if (root == null) {
   232→			root = x.initLevel(0);
   233→			nEntries++;
   234→			return;
   235→		}
   236→		if (!root.hasChildren()) {
   237→			double dist = d(root, x);
   238→			//initialize levels from current distance
   239→			int level = (int) log13(dist);
   240→			root.setLevel(level + 1);
   241→			Node<T> q = x.initLevel(level);
   242→			root.addChild(q, dist);
   243→			nEntries++;
   244→			return;
   245→		}
   246→		insert(root, x);
   247→		nEntries++;
   248→	}
   249→	
   250→	private void insert(Node<T> p, Node<T> x) {
   251→//		Algorithm 2 Simplified cover tree insertion
   252→//		function insert(cover tree p, data point x)
   253→//		1: if d(p;x) > covdist(p) then
   254→//		2: while d(p;x) > 2covdist(p) do
   255→//		3: Remove any leaf q from p
   256→//		4: p0  tree with root q and p as only child
   257→//		5: p  p0
   258→//		6: return tree with x as root and p as only child
   259→//		7: return insert (p,x)
   260→		double distPX = d(p,x); 
   261→		if (distPX > covdist(p)) {
   262→			//TODO reuse distPX in first iteration?!?
   263→			//while (d(p.point(), x) > BASE*covdist(p)) {
   264→			//TODO the above is WRONG! For example it does not work with [2,3],[5,4],[9,6],
   265→			//     resulting in a covDist([9,6]) that does not cover [2,3]
   266→			//  while (distPX + covdist(p)> BASE*covdist(p)) {
   267→			//Even better: we could use:
   268→			//  while (distPX + maxdist(p)> BASE*covdist(p)) {
   269→			//TODO above fix can be simplified:
   270→			while (distPX > (BASE-1)*covdist(p)) {
   271→				//3: Remove any leaf q from p
   272→				Node<T> q = p.removeAnyLeaf();
   273→				//4: p0 = tree with root q and p as only child
   274→				Node<T> p0 = q;
   275→				q.setLevel(p.getLevel() + 1);
   276→				q.addChild(p, d(q, p));
   277→				//5: p  p0
   278→				p = p0;
   279→				distPX = d(p,x);
   280→			}
   281→			//return tree with x as root and p as only child;
   282→			Node<T> newRoot = x.initLevel(p.getLevel() + 1);
   283→			newRoot.addChild(p, distPX);
   284→			//TODO set in caller?
   285→			this.root = newRoot;
   286→			return;
   287→		}
   288→		if (NEAREST_ANCESTOR) {
   289→			insert2NA(p,x, distPX);
   290→		} else {
   291→			insert2(p, x, distPX);
   292→		}
   293→	}
   294→
   295→	private Node<T> insert2(Node<T> p, Node<T> x, double distPX) { 
   296→//		function insert (cover tree p, data point x)
   297→//		prerequisites: d(p;x) <= covdist(p)
   298→//		1: for q 2 children(p) do
   299→//		2: if d(q;x) <= covdist(q) then
   300→//		3: q0  insert (q;x)
   301→//		4: p0   p with child q replaced with q0
   302→//		5: return p0
   303→//		6: return p with x added as a child
   304→
   305→		//1: for q : children(p) do
   306→		ArrayList<Node<T>> children = p.getOrCreateChildren();
   307→		double covDistQ = children.isEmpty()? 0 : covdist(children.get(0));
   308→		for (int i = 0; i < children.size(); i++) {
   309→			Node<T> q = children.get(i);
   310→			//2: if d(q;x) <= covdist(q) then
   311→			double distQX = d(q, x); 
   312→			if (distQX <= covDistQ) {
   313→				//3: q0  insert (q;x)
   314→				Node<T> qNew = insert2(q, x, distQX);
   315→				//4: p0   p with child q replaced with q0
   316→				if (qNew != q) {
   317→					p.replaceChild(i, qNew);
   318→				}
   319→				//5: return p0
   320→				p.adjustMaxDist(distPX);
   321→				return p;
   322→			}
   323→		}
   324→		//6: return p with x added as a child
   325→		p.addChild(x.initLevel(p.getLevel() - 1), distPX);
   326→		return p;
   327→//		return rebalance(p, x);
   328→	}
   329→
   330→	/**
   331→	 * Nearest ancestor insert
   332→	 * @param p
   333→	 * @param x
   334→	 * @param distPX
   335→	 * @return
   336→	 */
   337→	private Node<T> insert2NA(Node<T> p, Node<T> x, double distPX) { 
   338→//		function insert (cover tree p, data point x)
   339→//		prerequisites: d(p;x) <= covdist(p)
   340→
   341→		//insert into closest child!
   342→		
   343→		//1: for q : children(p) do
   344→		ArrayList<Node<T>> children = p.getOrCreateChildren();
   345→		double covDistQ = covDist(p.getLevel() - 1);
   346→		Node<T> best = null;
   347→		double distBest = Double.MAX_VALUE;
   348→		int posBest = -1;
   349→		for (int i = 0; i < children.size(); i++) {
   350→			Node<T> q = children.get(i);
   351→			//2: if d(q;x) <= covdist(q) then
   352→			double distQX = d(q, x); 
   353→			if (distQX <= covDistQ && distQX < distBest) {
   354→				distBest = distQX;
   355→				best = q;
   356→				posBest = i;
   357→			}
   358→		}
   359→		if (best != null) {
   360→			Node<T> q = best;
   361→			double distQX = distBest;
   362→			int i = posBest;
   363→			//3: q0  insert (q;x)
   364→			Node<T> qNew = insert2NA(q, x, distQX);
   365→			//4: p0   p with child q replaced with q0
   366→			if (qNew != q) {
   367→				p.replaceChild(i, qNew);
   368→			}
   369→			//5: return p0
   370→			p.adjustMaxDist(distPX);
   371→			return p;
   372→		}
   373→		//6: return p with x added as a child
   374→//		p.addChild(x.initLevel(p.getLevel() - 1), distPX);
   375→//		return p;
   376→		return rebalanceTZ(p, x, distPX);
   377→	}
   378→
   379→	private Node<T> rebalanceTZ(Node<T> p, Node<T> x, double distPX) {
   380→		//Rebalance to ensure the nearest-ancestor invariant:
   381→		//1) Find all nodes 'q' whose covdist && mindist overlaps with the new node x
   382→		//2) For all 'q' traverse all subnode 'r' and check if:
   383→		//   a) Parent-dist(r) > dist(x,q)-covdist(x)
   384→		//   b1) (1st level): dist(x,r) < parentDist(r)
   385→		//   b2)  
   386→		
   387→		//Remember the nearest-ancestor invariants only refers to the IMMEDIATE
   388→		//ancestor!
   389→		//Convention: 'x' is a new node that is inserted into a node 'p'. The other
   390→		//children or 'p' are named 'q'. Any children of 'q' or 'x' are named 'r'.
   391→		//Any children (descendants?) of any 'r' a named 's'.
   392→		//Implications of invariant: 
   393→		//- If we childnode r of q to x, we try to keep it on the same level,
   394→		//  which means we can move it together with all it's children.
   395→		//  -> Problem if we move r1 from q1 and r2 from q2 into x,
   396→		//     there is no guarantee that r1 and r2 have a minimum distance of
   397→		//     cov-dist, in other words they may need 'merging'!
   398→		//     TODO is that geometrically possible?
   399→		//  -> Merging entails a bigger problem: 
   400→		//     If we reinsert all the children (r1, r2, ..) into x, on of the
   401→		//     subchildren s of r, may be inserted directly into 'x', even though
   402→		//     x may not be it's nearest ancestor (that can only happen for children
   403→		//     or r's, because ...)
   404→		//Solution: 
   405→		//  - r's can be directly re-inserted into x, but any children of r's
   406→		//     need to be queued and reinserted a root level....
   407→		//  - Reinsertion of children r of q into x is fine as long as none 
   408→		//    of the reinserted r's overlap (more precisely if they do not have children
   409→		//    that could be in any other r of x.
   410→		//  - Optimization: Even if an r cannot be reinserted into x, it's 's' may be 
   411→		//    reinsertable if there is only one matching r in x.
   412→		//  - In other words, any new r of x that overlaps with any 
   413→		//  In orher words: Direct reinsertion is fine, as long as the new level is equal 
   414→		//  or lower that the previous level.
   415→		//
   416→		//Algorithm for reinsertion:
   417→		//- if there is no overlapping r1 in x: Insert r2 including all children
   418→		//- If there is an overlapping r1, add r2 to List of reinsertables.
   419→		//  for every child s or r2, check whether there is only one matching r in x.
   420→		//  - if yes: insert s into that r. Then: recurse for children of s or add to reinsertables 
   421→		//  - if no: add 's' and all it's children to reinsertables.
   422→		//All reinsertion can be done directly into 'p' (parent of q and x) because
   423→		//we know that there are at least two nodes in p (x and q) that can contain the
   424→		//moved node. Insert directly into 'x' would be good for all direct children of
   425→		//'q' because we know that 'x' is the closest ancestor. For sub-children of 'q'
   426→		//we cannot guarantee that. If one of these subchildren can be reinsertedinto
   427→		//any r of x, it would be fine. But if it is inserted directly in 'x', we would need
   428→		//to verify that there is no other q in p that would be a better ancestor.
   429→		//However, if we reinsert these subchildren in to 'p', we know that there
   430→		//is at least one 'q' (namely it's original parent) that contain it, so there
   431→		//is no need that 'p' is the closest ancestor because 'p' would never be a direct ancestor.
   432→		//In short: Insert into 'x' if possible, otherwise reinsert into 'p'.
   433→		ArrayList<Node<T>> reinsert = null;
   434→		//init, because we may use (insert, covdist, ..) this node before we add it to p.
   435→		x.initLevel(p.getLevel() - 1);
   436→		if (p.hasChildren()) {
   437→			ArrayList<Node<T>> children = p.getChildren();
   438→			double covDist = covDist(p.getLevel() - 1);
   439→			//Check all siblings q of x whether they may contain point that need
   440→			//to be reassigned. 'q' itself cannot require reassignment. 
   441→			for (int i = 0; i < children.size(); i++) {
   442→				Node<T> q = children.get(i);
   443→				if (q.hasChildren()) {
   444→					double distQX = d(q, x); 
   445→					if (distQX <= 2*covDist
   446→							&& distQX <= covDist + q.maxdist(this)) {
   447→						reinsert = (reinsert != null) ? reinsert : new ArrayList<>();
   448→						rebalanceSub(x, q, reinsert, distQX);
   449→					}
   450→				}
   451→			}
   452→		}
   453→		p.addChild(x, distPX);
   454→		if (reinsert != null) {
   455→			for (int i = 0; i < reinsert.size(); i++) {
   456→				Node<T> q = reinsert.get(i);
   457→				insert2NA(p, q, distPX);
   458→			}
   459→		}
   460→		return p;
   461→	}
