   463→	/**
   464→	 * 
   465→	 * @param x New ancestor
   466→	 * @param q Current ancestor
   467→	 * @param reinsert resinsertion queue 
   468→	 */
   469→	private void rebalanceSub(Node<T> x, Node<T> q, ArrayList<Node<T>> reinsert,
   470→			double distQX) {
   471→		if (q.hasChildren()) {
   472→			ArrayList<Node<T>> children = q.getChildren();
   473→			for (int i = 0; i < children.size(); i++) {
   474→				Node<T> r = children.get(i);
   475→				double distRQ = r.getDistanceToParent();
   476→				if (distRQ*2 > distQX) {
   477→					double distRX = d(r, x);
   478→					if (distRX < distRQ) {
   479→						//okay, needs reinsertion
   480→						q.removeChild(i--);
   481→						reinsert(x, r, reinsert, distRX);
   482→					}
   483→				}
   484→			}
   485→		}
   486→	}
