   566→	private Node<T> rebalance(Node<T> p, Node<T> q, Node<T> x, 
   567→			ArrayList<Node<T>> moveSet, ArrayList<Node<T>> staySet) {
   568→//	function rebalance (cover trees p and q, point x)
   569→//	prerequisites: p is an ancestor of q
   570→//	1: if d(p;q) > d(q;x) then
   571→//	2: moveset; stayset   /0
   572→//	3: for r 2 descendants(q) do
   573→//	4: if d(r; p) > d(r;x) then
   574→//	5: moveset  moveset [frg
   575→//	6: else
   576→//	7: stayset  stayset [frg
   577→//	8: return (null;moveset; stayset)
   578→//	9: else
   579→//	10: moveset0; stayset0   /0
   580→//	11: q0  q
   581→//	12: for r 2 children(q) do
   582→//	13: (r0;moveset; stayset) rebalance (p; r;x)
   583→//	14: moveset0  moveset[moveset0
   584→//	15: stayset0  stayset[stayset0
   585→//	16: if r0 = null then
   586→//	17: q0  q with the subtree r removed
   587→//	18: else
   588→//	19: q0  q with the subtree r replaced by r0
   589→//	20: for r 2 stayset0 do
   590→//	21: if d(r;q)0  covdist(q)0 then
   591→//	22: q0  insert(q0; r)
   592→//	23: stayset0  stayset0􀀀frg
   593→//	24: return (q0;moveset0; stayset0)
   594→		
   595→		// 1: if d(p;q) > d(q;x) then
   596→		if (d(p, q) > d(q, x)) {
   597→			//2: moveset; stayset   /0
   598→			//3: for r 2 descendants(q) do
   599→			if (q.hasChildren()) {
   600→				ArrayList<Node<T>> children = q.getChildren();
   601→				for (int i = 0; i < children.size(); i++) {
   602→					Node<T> r = children.get(i);
   603→					//4: if d(r; p) > d(r;x) then
   604→					if (d(r, p) > d(r, x)) {
   605→						//5: moveset  moveset [frg
   606→						moveSet.add(r);
   607→					} else {
   608→						//6: else
   609→						//7: stayset  stayset [frg
   610→						staySet.add(r);
   611→					}
   612→				}
   613→			}
   614→			//	8: return (null;moveset; stayset)
   615→			return null;
   616→			//	9: else
   617→		} else {  	
   618→			//10: moveset0; stayset0   /0
   619→			//11: q0  q
   620→			Node<T> q0 = q;
   621→			//12: for r 2 children(q) do
   622→			if (q.hasChildren()) {
   623→				ArrayList<Node<T>> children = q.getChildren();
   624→				for (int i = 0; i < children.size(); i++) {
   625→					Node<T> r = children.get(i);
   626→					//13: (r0;moveset; stayset) rebalance (p; r;x)
   627→					//TODO moveSet/stayset?????
   628→					Node<T> r0 = rebalance(p, r, x, moveSet, staySet); 
   629→					//14: moveset0 = moveset + moveset0
   630→					//15: stayset0 = stayset + stayset0
   631→					//16: if r0 = null then
   632→					if (r0 == null) {
   633→						//17: q0  q with the subtree r removed
   634→						q0 = q;
   635→						q0.removeChild(i);
   636→					} else {
   637→						//18: else
   638→						//19: q0  q with the subtree r replaced by r0
   639→						q0 = q;
   640→						q0.replaceChild(i, r0);
   641→						q0.adjustMaxDist(d(q0, r0));
   642→					}
   643→				}
   644→			}
   645→			//20: for r 2 stayset0 do
   646→			for (int i = 0; i < staySet.size(); i++) {
   647→				Node<T> r = staySet.get(i);
   648→				//TODO typo, apostrophe _inside_ ()
   649→				//21: if d(r;q)0 <= covdist(q)0 then
   650→				if (d(r,q0) <= covdist(q0)) {
   651→					//22: q0  insert(q0; r)
   652→					//q0 = insert(q0, r); TODO report?????
   653→					q0 = insert2(q0, r, d(r,q0));
   654→					//23: stayset0 = stayset0 - {r}
   655→					//TODO optimize?
   656→					staySet.remove(i--);
   657→				}
   658→			}
   659→			//24: return (q0;moveset0; stayset0)
   660→			return q0;
   661→		}
   662→	}
