   736→	private void findNearestNeighbor(Node<T> p, PointEntry<T> x, final PointEntryKnn<T> y,
   737→			double distPX) {
   738→//		Algorithm 1 Find nearest neighbor
   739→//		function findNearestNeighbor(cover tree p, query
   740→//		point x, nearest neighbor so far y)
   741→//		1: if d(p;x) < d(y;x) then
   742→//		2: y  p
   743→//		3: for each child q of p sorted by distance to x do
   744→//		4: if d(y;x) > d(y;q)-maxdist(q) then
   745→//		5: y findNearestNeighbor(q;x;y)
   746→//		6: return y
   747→		if (distPX < y.dist()) {
   748→			y.set(p.point(), distPX);
   749→		}
   750→
   751→		if (p.hasChildren()) {
   752→			ArrayList<Node<T>> children = p.getChildren();
   753→			for (int i = 0; i < children.size(); i++) {
   754→				Node<T> q = children.get(i);
   755→				
   756→				//Exclude children that are (compared to x) too close to the node or too far away
   757→				//to contain any useful points.
   758→				double distPQ = q.getDistanceToParent();
   759→				if (distPQ+q.maxdist(this) < distPX-y.dist()
   760→						|| distPQ-q.maxdist(this)> distPX+y.dist()) {
   761→					continue;
   762→				}
   763→
   764→				//TODO report to authors: use d(y;x) > d(_X_;q)-maxdist(q)
   765→				double distQX = d(x, q.point());
   766→				nDist1NN++;
   767→				if (y.dist() > (distQX - q.maxdist(this))) {
   768→					findNearestNeighbor(q, x, y, distQX);
   769→				}
   770→			}
   771→		}
   772→	}
