   951→	private double getGlobalMaxDist(Node<T> p, Node<T> node, double currentMax) {
   952→		double distOfThisNode = d(p, node);
   953→		currentMax = Math.max(currentMax, distOfThisNode);
   954→		if (node.hasChildren() && distOfThisNode + node.maxdist(this) > currentMax) {
   955→			for (Node<T> sub : node.getChildren()) {
   956→				currentMax = Math.max(currentMax, getGlobalMaxDist(p, sub, currentMax));
   957→			}
   958→		}
   959→		return currentMax;
   960→	}
