   421→		//  - if no: add 's' and all it's children to reinsertables.
   422→		//All reinsertion can be done directly into 'p' (parent of q and x) because
   423→		//we know that there are at least two nodes in p (x and q) that can contain the
   424→		//moved node. Insert directly into 'x' would be good for all direct children of
   425→		//'q' because we know that 'x' is the closest ancestor. For sub-children of 'q'
   426→		//we cannot guarantee that. If one of these subchildren can be reinsertedinto
   427→		//any r of x, it would be fine. But if it is inserted directly in 'x', we would need
   428→		//to verify that there is no other q in p that would be a better ancestor.
   429→		//However, if we reinsert these subchildren in to 'p', we know that there
   430→		//is at least one 'q' (namely it's original parent) that contain it, so there
   431→		//is no need that 'p' is the closest ancestor because 'p' would never be a direct ancestor.
   432→		//In short: Insert into 'x' if possible, otherwise reinsert into 'p'.
   433→		ArrayList<Node<T>> reinsert = null;
   434→		//init, because we may use (insert, covdist, ..) this node before we add it to p.
   435→		x.initLevel(p.getLevel() - 1);
   436→		if (p.hasChildren()) {
   437→			ArrayList<Node<T>> children = p.getChildren();
   438→			double covDist = covDist(p.getLevel() - 1);
   439→			//Check all siblings q of x whether they may contain point that need
   440→			//to be reassigned. 'q' itself cannot require reassignment. 
   441→			for (int i = 0; i < children.size(); i++) {
   442→				Node<T> q = children.get(i);
   443→				if (q.hasChildren()) {
   444→					double distQX = d(q, x); 
   445→					if (distQX <= 2*covDist
   446→							&& distQX <= covDist + q.maxdist(this)) {
   447→						reinsert = (reinsert != null) ? reinsert : new ArrayList<>();
   448→						rebalanceSub(x, q, reinsert, distQX);
   449→					}
   450→				}
   451→			}
   452→		}
   453→		p.addChild(x, distPX);
   454→		if (reinsert != null) {
   455→			for (int i = 0; i < reinsert.size(); i++) {
   456→				Node<T> q = reinsert.get(i);
   457→				insert2NA(p, q, distPX);
   458→			}
   459→		}
   460→		return p;
   461→	}
