   899→	private void getStats(Node<T> node, CTStats stats) {
   900→		stats.nEntries++;
   901→		stats.nNodes++;
   902→		stats.minLevel = Math.min(stats.minLevel, node.getLevel());
   903→		stats.maxLevel = Math.max(stats.maxLevel, node.getLevel());
   904→		stats.maxDepth = stats.maxLevel - stats.minLevel;
   905→		stats.sumLevel += node.getLevel();
   906→		
   907→		if (node.hasChildren()) {
   908→			double maxDist = -1;
   909→			stats.maxNodeSize = Math.max(stats.maxNodeSize, node.getChildren().size());
   910→			for (Node<T> c : node.getChildren()) {
   911→				double distToParent = d(node, c);
   912→				if (distToParent != c.getDistanceToParent()) {
   913→					throw new IllegalStateException(
   914→							"ParentDist: " + distToParent + " / " + c.getDistanceToParent());
   915→				}
   916→				if (node.getLevel() != c.getLevel() + 1) {
   917→					throw new IllegalStateException(
   918→							"Level: " + node.getLevel() + " / " + c.getLevel());
   919→				}
   920→				
   921→				getStats(c, stats);
   922→			}
   923→			
   924→			maxDist = getGlobalMaxDist(node); 
   925→			stats.sumMaxDist+=maxDist;
   926→
   927→			if (maxDist != node.maxdist(this)) {
   928→				throw new IllegalStateException(
   929→						"Maxdist: " + maxDist + " / " + node.maxdist(this) +
   930→						" Node:" + toStringNode(new StringBuilder(), node));
   931→			}
   932→			if (maxDist > covdist(node))  {
   933→				throw new IllegalStateException("Maxdist/maxdist()/CovDist: " + 
   934→						maxDist + " / " + node.maxdist(this) + " / " + covdist(node));
   935→			}
   936→		} else {
   937→			stats.nLeaf++;
   938→		}
   939→	}
   940→	
   941→	private double getGlobalMaxDist(Node<T> node) {
   942→		double currentMax = 0;
   943→		if (node.hasChildren()) {
   944→			for (Node<T> sub : node.getChildren()) {
   945→				currentMax = getGlobalMaxDist(node, sub, currentMax);
   946→			}
   947→		}
   948→		return currentMax;
   949→	}
   950→	
   951→	private double getGlobalMaxDist(Node<T> p, Node<T> node, double currentMax) {
   952→		double distOfThisNode = d(p, node);
   953→		currentMax = Math.max(currentMax, distOfThisNode);
   954→		if (node.hasChildren() && distOfThisNode + node.maxdist(this) > currentMax) {
   955→			for (Node<T> sub : node.getChildren()) {
   956→				currentMax = Math.max(currentMax, getGlobalMaxDist(p, sub, currentMax));
   957→			}
   958→		}
   959→		return currentMax;
   960→	}
   961→	
   962→	 public static class CTStats extends Stats {
   963→		double sumMaxDist = 0;
   964→		
   965→		CTStats(CoverTree<?> tree) {
   966→			super(tree.nDistCalc, tree.nDist1NN, tree.nDistKNN);
   967→		}
   968→		
   969→		@Override
   970→		public String toString() {
   971→			return super.toString() +
   972→					";sumMaxDist=" + sumMaxDist;
   973→		}
   974→	}
   975→
   976→	Node<T> getRoot() {
   977→		return root;
   978→	}
   979→	
   980→	@Override
   981→	public String toString() {
   982→		return this.getClass().getSimpleName() + 
   983→				";BASE=" + BASE +  
   984→				";NEAREST_ANCESTOR=" + NEAREST_ANCESTOR + 
   985→				";DistFn=" + PointDistance.getName(dist);
   986→	}
   987→
   988→}
