   108→	public static <T> CoverTree<T> create(PointEntry<T>[] data, double base,
   109→			PointDistance distFn) {
   110→		if (data == null || data.length == 0) {
   111→			throw new IllegalStateException("Bulk load with empty data no possible.");
   112→		}
   113→		CoverTree<T> tree = new CoverTree<>(data[0].point().length, base, distFn);
   114→		if (data.length == 1) {
   115→			tree.root = new Node<>(data[0], 0);
   116→			tree.nEntries++;
