   118→		}
   119→		
   120→		//The point of bulk load is (currently) only to initialize the tree with a
   121→		//suitable 'level' and 'root', which should avoid any problems with having 
   122→		//to pull up leaves to replace the root. Bulk loading thus allows a BASE < 2.0 .
   123→		
   124→		PointEntry<T> newRoot = data[0];
