   213→		sb.append(";MaxD=")
   214→		//.append(node.maxdist(this))
   215→		.append("/").append(node.maxdistInternal());
   216→		sb.append(";ParD=").append(node.getDistanceToParent());
   217→		sb.append(";CovD=").append(covdist(node));
   218→		if (node.hasChildren()) {
   219→			sb.append(";nC=").append(node.getChildren().size());
   220→		} else {
   221→			sb.append(";nC=0");
   222→		}
   223→		sb.append(";coord=").append(Arrays.toString(node.point().point()));
   224→		return sb;
   225→	}
