   330→	/**
   331→	 * Nearest ancestor insert
   332→	 * @param p
   333→	 * @param x
   334→	 * @param distPX
   335→	 * @return
   336→	 */
   337→	private Node<T> insert2NA(Node<T> p, Node<T> x, double distPX) { 
   338→//		function insert (cover tree p, data point x)
   339→//		prerequisites: d(p;x) <= covdist(p)
   340→
   341→		//insert into closest child!
   342→		
   343→		//1: for q : children(p) do
   344→		ArrayList<Node<T>> children = p.getOrCreateChildren();
   345→		double covDistQ = covDist(p.getLevel() - 1);
   346→		Node<T> best = null;
   347→		double distBest = Double.MAX_VALUE;
   348→		int posBest = -1;
   349→		for (int i = 0; i < children.size(); i++) {
   350→			Node<T> q = children.get(i);
   351→			//2: if d(q;x) <= covdist(q) then
   352→			double distQX = d(q, x); 
   353→			if (distQX <= covDistQ && distQX < distBest) {
   354→				distBest = distQX;
   355→				best = q;
   356→				posBest = i;
   357→			}
   358→		}
   359→		if (best != null) {
   360→			Node<T> q = best;
   361→			double distQX = distBest;
   362→			int i = posBest;
   363→			//3: q0  insert (q;x)
   364→			Node<T> qNew = insert2NA(q, x, distQX);
   365→			//4: p0   p with child q replaced with q0
   366→			if (qNew != q) {
   367→				p.replaceChild(i, qNew);
   368→			}
   369→			//5: return p0
   370→			p.adjustMaxDist(distPX);
   371→			return p;
   372→		}
   373→		//6: return p with x added as a child
   374→//		p.addChild(x.initLevel(p.getLevel() - 1), distPX);
   375→//		return p;
   376→		return rebalanceTZ(p, x, distPX);
   377→	}
