   488→	private void reinsert(Node<T> x, Node<T> rNew, ArrayList<Node<T>> reinsertLater,
   489→			double distRX) {
   490→		ArrayList<Node<T>> children = x.getOrCreateChildren();
   491→		double covDistR = covdist(rNew);
   492→		for (int i = 0; i < children.size(); i++) {
   493→			Node<T> rx = children.get(i);
   494→			double distRxRNew = d(rx, rNew);
   495→			//Overlap of covers?
   496→			if (distRxRNew < 2*covDistR) {
   497→				if (distRxRNew < covDistR) {
   498→					//reinsert rNew into rX: not possible, reinsert in parent
   499→					rNew.clearAndRemoveAllChildren(reinsertLater);
   500→					reinsertLater.add(rNew);
   501→					return;
   502→				} else if (rNew.maxdist(this) > distRxRNew-covDistR) {
   503→					//rNew's children overlap with rX: 
   504→					//reinsert rNew and reinsert children into parent.
   505→					//But we need to keep checking other rX.
   506→					rNew.clearAndRemoveAllChildren(reinsertLater);
   507→				}
   508→			} 
   509→		}
   510→		if (distRX + rNew.maxdist(this) > covdist(x)) {
   511→			//TODO only clear those that violate the limit
   512→			rNew.clearAndRemoveAllChildren(reinsertLater);
   513→		}
   514→		x.addChild(rNew, distRX);
   515→	}
