   517→	private Node<T> rebalance(Node<T> p, Node<T> x) {
   518→//  	function rebalance(cover trees p, data point x)
   519→//  	prerequisites: x can be added as a child of p without violating
   520→//      the covering or separating invariants
   521→//		1: create tree x0 with root node x at level level(p)􀀀1 x0
   522→//		contains no other points
   523→//		2: p0   p
   524→//		3: for q 2 children(p) do
   525→//		4: (q0;moveset; stayset) rebalance (p;q;x)
   526→//		5: p0   p0 with child q replaced with q0
   527→//		6: for r 2 moveset do
   528→//		7: x0  insert(x0; r)
   529→//		8: return p0 with x0 added as a child
   530→	
   531→		//	1: create tree x0 with root node x at level level(p)-1 x0
   532→		//	contains no other points
   533→		Node<T> x0 = x.initLevel(p.getLevel() - 1); 
   534→		//	2: p0   p
   535→		Node<T> p0 = p;
   536→		//	3: for q 2 children(p) do
   537→		if (p.hasChildren()) {
   538→			ArrayList<Node<T>> children = p.getChildren();
   539→			ArrayList<Node<T>> moveSet = new ArrayList<>();
   540→			ArrayList<Node<T>> staySet = new ArrayList<>();
   541→			for (int i = 0; i < children.size(); i++) {
   542→				Node<T> q = children.get(i);
   543→				//	4: (q0;moveset; stayset) rebalance (p;q;x)
   544→				moveSet.clear();
   545→				staySet.clear();
   546→				Node<T> q0 = rebalance(p, q, x, moveSet, staySet);
   547→				//	5: p0   p0 with child q replaced with q0
   548→				if (q0 != null) {
   549→					p0.replaceChild(i, q0);
   550→				}
   551→				q0.adjustMaxDist(d(p0, q0));
   552→				//TODO adjust max?!?!
   553→				//	6: for r 2 moveset do
   554→				for (int j = 0; j < moveSet.size(); j++) {
   555→					//	7: x0  insert(x0; r)
   556→					//x0 = insert(x0, moveSet.get(j)); //TODO report!
   557→					x0 = insert2(x0, moveSet.get(j), d(x0, moveSet.get(j)));
   558→				}
   559→			}
   560→		}
   561→		//	8: return p0 with x0 added as a child
   562→		p0.addChild(x0, d(p0, x0));
   563→		return p0;
   564→	}
