   794→		if (candidates.size() < k) {
   795→			candidates.add(new PointEntryKnn<>(nn.point(), nn.value(), distPX));
   796→			candidates.sort(comparator);
   797→		} else if (distPX < candidates.get(k-1).dist()) {
   798→			candidates.remove(k-1);
   799→			candidates.add(new PointEntryKnn<>(nn.point(), nn.value(), distPX));
   800→			candidates.sort(comparator);
   801→		}
   802→
   803→		if (p.hasChildren()) {
   804→			ArrayList<Node<T>> children = p.getChildren();
   805→			for (int i = 0; i < children.size(); i++) {
   806→				Node<T> q = children.get(i);
   807→				double distCurrentWorst = candidates.get(candidates.size() - 1).dist();
   808→				
   809→				//Exclude children that are (compared to x) too close to the node or too far away
   810→				//to contain any useful points.
   811→				double distPQ = q.getDistanceToParent();
   812→				if (distPQ+q.maxdist(this) < distPX-distCurrentWorst
   813→						|| distPQ-q.maxdist(this)> distPX+distCurrentWorst) {
   814→					continue;
   815→				}
   816→				
   817→				//TODO cache d(y, x)
   818→	//			if (d(y, x) > (d(y, q.point()) - q.maxdist(this))) {
   819→	//				y = findNearestNeighbor(q, x, y);
   820→	//			}
   821→				double distQX = d(q.point(), x);
   822→				nDistKNN++;
