			}
		});

		List<DefaultEdge> toRemove = new ArrayList<>();
		graph.edgeSet().forEach(e -> {
			PShape a = graph.getEdgeSource(e);
			PShape b = graph.getEdgeTarget(e);
			if (!classes.get(a).equals(classes.get(b))) {
				toRemove.add(e);
			}
		});
