	 * @since 1.4.0
	 */
	public static PShape smoothMesh(PShape mesh, double displacementCutoff, boolean preservePerimeter) {
		displacementCutoff = Math.max(displacementCutoff, 1e-3);
		PMesh m = new PMesh(mesh);

